'use strict';
/**
 * UWorld Buzz Fun — Pulmonology.
 *
 * One card per UWorld Adventure pulmonology question: the long case is cut
 * down to the one concept it tests, so a player learns what the question
 * teaches without wading through the vignette. Written in our own words —
 * no stem or explanation text is copied.
 *
 * Row: [sourceId, type, topic, clue, answer, [3 wrong answers], [points]]
 *
 * The answer is written in the SAME style and length as the wrong answers —
 * no bracketed hints, no extra detail that gives it away (check.js enforces
 * this). The explanation is three full sentences: why the answer is right,
 * the mechanism behind it, and why the tempting alternative is wrong or the
 * related fact the exam asks next.
 *
 * sourceId is the UWorld Adventure question it was built from (PL-nnn); the
 * card id is BFU-<sourceId>. Run `node server/buzzfun/check.js` after editing.
 */
module.exports = [
  // ── PL-052 … PL-101 ──────────────────────────────────────────────────────
  ['PL-052', 'MECHANISM', 'Gas exchange', 'Why arterial PO₂ dips slightly below end-capillary PO₂ in a healthy person', 'Mixing with deoxygenated blood', ['Increased dead space ventilation', 'Diffusion-limited oxygenation', 'Shift in the Hb–O₂ curve'], ['A small amount of venous blood normally joins oxygenated blood on its way to the left heart, so arterial PO₂ ends up a few mm Hg lower than end-capillary PO₂.', 'That blood comes from the bronchial veins, which drain into the pulmonary veins, and the Thebesian veins, which drain straight into the left ventricle.', 'This is a physiologic shunt, and because shunted blood never meets alveolar gas, giving extra oxygen barely changes it.']],
  ['PL-053', 'ASSOCIATION', 'Asthma & COPD', 'Suspected asthma with normal spirometry — which drug provokes bronchospasm to prove it?', 'Methacholine', ['Albuterol', 'Ipratropium', 'Theophylline'], ['Methacholine is a muscarinic agonist, and inhaling it narrows hyperreactive airways at doses that leave normal airways untouched.', 'A fall in FEV₁ of 20% or more at a low dose supports the diagnosis of asthma when resting spirometry is normal.', 'Albuterol, ipratropium and theophylline all open the airways, so they can show reversibility but cannot provoke narrowing.']],
  ['PL-054', 'DEFICIENCY', 'Cystic fibrosis', 'CF patient with fat malabsorption: pancreatic duct lining turns into keratinizing squamous cells', 'Vitamin A deficiency', ['Vitamin D deficiency', 'Vitamin K deficiency', 'Vitamin E deficiency'], ['Vitamin A keeps specialised epithelium differentiated, so without it columnar and cuboidal linings change into squamous epithelium (squamous metaplasia).', 'Pancreatic insufficiency in cystic fibrosis causes fat malabsorption, and with it loss of all the fat-soluble vitamins A, D, E and K.', 'Vitamin A deficiency also causes night blindness, Bitot spots and dry, keratinised conjunctiva.']],
  ['PL-055', 'MECHANISM', 'Pharmacology', 'Omalizumab in severe allergic asthma — how does it help?', 'Decreasing airway inflammation', ['Increasing smooth muscle relaxation', 'Decreasing airway collagen deposition', 'Increasing pulmonary vasodilation'], ['Omalizumab is a monoclonal antibody that binds free IgE, so less IgE is available to coat mast cells and basophils.', 'Mast cells without IgE on their surface are not triggered by allergens, so the inflammatory cascade in the airway wall never starts.', 'It does not relax smooth muscle directly; it is an add-on controller for severe allergic asthma with high IgE.']],
  ['PL-056', 'BUZZWORD', 'TB & fungi', 'Mississippi farmer, granulomas, broad-based budding yeast, normal immunity', 'Blastomyces dermatitidis', ['Candida albicans', 'Mucor species', 'Pneumocystis jirovecii'], ['Blastomyces is a large yeast with a thick double-contoured wall and a single bud attached by a broad base.', 'It is endemic east of the Mississippi and around the Great Lakes, and it can spread from the lungs to the skin and bone.', 'Unlike Candida, Mucor and Pneumocystis, it readily infects people with a normal immune system; treat with itraconazole.']],
  ['PL-057', 'ASSOCIATION', 'Sleep & breathing control', 'Obstructive sleep apnea implant stimulates which nerve to push the tongue forward?', 'Hypoglossal nerve', ['Phrenic nerve', 'Recurrent laryngeal nerve', 'Lingual nerve'], ['The hypoglossal nerve (CN XII) drives the genioglossus, which pulls the tongue forward and opens the oropharynx.', 'In obstructive sleep apnea the pharynx collapses during sleep, causing loud snoring, gasping apneas and daytime sleepiness.', 'CPAP and weight loss come first; hypoglossal nerve stimulation is used when CPAP fails or is not tolerated.']],
  ['PL-058', 'MECHANISM', 'Gas exchange', 'Hemoglobin loading O₂ in the lungs releases what?', 'Protons', ['Chloride', 'Oxygen', 'Phosphate'], ['Oxygenated hemoglobin is a stronger acid than deoxygenated hemoglobin, so it gives up hydrogen ions as it loads oxygen in the lungs.', 'Those protons combine with bicarbonate to form CO₂, which is then breathed out; this is the Haldane effect.', 'In the tissues the reverse happens: hydrogen ions and CO₂ lower hemoglobin\'s oxygen affinity and help unload oxygen (the Bohr effect).']],
  ['PL-059', 'ASSOCIATION', 'Asthma & COPD', 'Smoker, hyperresonant chest, flat diaphragm — expected PFT pattern?', '↑ TLC with a low FEV₁/FVC', ['↓ TLC with a normal FEV₁/FVC', '↑ TLC with a normal RV', '↓ TLC with a raised RV'], ['COPD is an obstructive disease, so the FEV₁/FVC ratio falls below 0.7.', 'Loss of elastic recoil lets airways collapse on expiration, trapping air and raising residual volume and total lung capacity.', 'A low TLC would instead point to restrictive disease such as fibrosis.']],
  ['PL-060', 'BUZZWORD', 'Lung structure', 'Alveolar lining wiped out by NO₂ — which cell regrows it?', 'Type II pneumocytes', ['Type I pneumocytes', 'Club cells', 'Alveolar macrophages'], ['Type II pneumocytes are the stem cells of the alveolus: they divide and differentiate into new type I cells after injury.', 'They also make surfactant, which lowers surface tension and stops alveoli collapsing.', 'Type I cells cover most of the surface but cannot divide, and club cells repair the bronchioles rather than the alveoli.']],
  ['PL-061', 'ASSOCIATION', 'Interstitial lung disease', 'Rheumatoid arthritis patient on years of methotrexate, bilateral reticular opacities', 'Pulmonary fibrosis', ['Obstructive lung disease', 'Pulmonary hypertension', 'Bilateral atelectasis'], ['Rheumatoid arthritis can cause interstitial lung disease by itself, often in a usual interstitial pneumonia pattern.', 'Methotrexate adds a second risk, because it can cause hypersensitivity pneumonitis that progresses to fibrosis.', 'Fibrosis gives a restrictive pattern: low TLC, a normal or high FEV₁/FVC ratio and a low DLCO.']],
  ['PL-062', 'BUZZWORD', 'Lung transplant', 'Months after lung transplant: dry cough, progressive obstruction, scarred small airways', 'Chronic transplant rejection', ['Acute transplant rejection', 'Ischemia–reperfusion injury', 'Opportunistic infection'], ['Chronic rejection of a lung transplant shows up as bronchiolitis obliterans: fibrous tissue plugs and obliterates the small airways.', 'Because the small airways close off, lung function becomes progressively obstructive despite good adherence to medication.', 'Acute rejection is different: it occurs in the first months and shows lymphocytes cuffing small vessels.']],
  ['PL-063', 'TRIAD', 'Pulmonary vascular', 'Young woman, exertional dyspnea, loud P2, right heart strain, family history', 'Pulmonary hypertension', ['Pulmonic valve stenosis', 'Hypertrophic cardiomyopathy', 'Hypertensive heart disease'], ['A loud pulmonic component of S2, a right ventricular heave and tricuspid regurgitation are signs of high pressure in the pulmonary arteries.', 'A family history suggests heritable pulmonary arterial hypertension, usually from an inactivating BMPR2 mutation.', 'Pulmonary hypertension means a mean pulmonary artery pressure above 20 mm Hg at rest.']],
  ['PL-064', 'ASSOCIATION', 'Lung cancer & pleura', 'Digital clubbing in an adult ex-smoker with clear lungs', 'Lung cancer', ['Chronic bronchitis', 'Iron deficiency anemia', 'Plaque psoriasis'], ['In adults the most common cause of clubbing is lung cancer, especially adenocarcinoma.', 'Other causes include bronchiectasis, cystic fibrosis, pulmonary fibrosis and cyanotic heart disease.', 'Uncomplicated COPD does not cause clubbing, so new clubbing in a smoker should prompt a search for cancer.']],
  ['PL-065', 'ASSOCIATION', 'Pneumonia', 'Improving from influenza, then high fever and purulent sputum again', 'Staphylococcus aureus', ['Klebsiella pneumoniae', 'Listeria monocytogenes', 'Cytomegalovirus'], ['Influenza damages the ciliated lining of the airway, which lets bacteria take hold a few days later.', 'The classic organisms in post-influenza pneumonia are Streptococcus pneumoniae, Staphylococcus aureus and Haemophilus influenzae.', 'S. aureus pneumonia is often severe and can cavitate, forming abscesses or pneumatoceles.']],
  ['PL-066', 'MECHANISM', 'Cystic fibrosis', 'ΔF508 CFTR — what goes wrong with the protein?', 'Abnormal post-translational processing', ['Decreased gene transcription', 'Truncated protein on the surface', 'Increased chloride conductivity'], ['The ΔF508 mutation deletes one phenylalanine, so the CFTR protein is made but folds incorrectly.', 'The misfolded protein is held in the endoplasmic reticulum and destroyed by the proteasome before it can reach the cell surface.', 'This is the most common cystic fibrosis mutation; the disease is autosomal recessive and diagnosed with a sweat chloride of 60 mmol/L or more.']],
  ['PL-067', 'MECHANISM', 'Pulmonary vascular', 'Left heart failure with pulmonary edema — which Starling force is abnormal?', 'Raised capillary hydrostatic pressure', ['Raised capillary permeability', 'Reduced plasma oncotic pressure', 'Blocked lymphatic drainage'], ['A failing left ventricle backs pressure up into the pulmonary capillaries, pushing fluid out faster than normal.', 'The lymphatics speed up to remove it, and edema appears only once filtration outpaces them.', 'Permeability stays normal, so the fluid is a low-protein transudate; leaky capillaries are the mechanism in ARDS instead.']],
  ['PL-068', 'MECHANISM', 'Pharmacology', 'Exercise-induced bronchospasm prevented with a leukotriene receptor blocker', 'Montelukast', ['Zileuton', 'Fluticasone', 'Ipratropium'], ['Montelukast blocks the CysLT1 receptor, so leukotrienes C4, D4 and E4 cannot constrict the airway.', 'Zileuton works one step earlier, by inhibiting 5-lipoxygenase, and needs liver enzyme monitoring.', 'Montelukast carries a warning for neuropsychiatric effects, including mood changes and suicidal thoughts.']],
  ['PL-069', 'MECHANISM', 'Pulmonary vascular', 'COPD with chronic hypoxemia, raised JVP and leg edema — what is increased?', 'Right ventricular afterload', ['Left ventricular preload', 'Pulmonary capillary wedge pressure', 'Pulmonary arterial compliance'], ['Chronic hypoxemia makes the pulmonary arterioles constrict, which raises pulmonary vascular resistance.', 'The right ventricle has to pump against that resistance, hypertrophies and eventually fails: this is cor pulmonale.', 'The wedge pressure stays normal, because the problem lies upstream of the left heart.']],
  ['PL-070', 'MECHANISM', 'TB & fungi', 'Which effector cells control Mycobacterium tuberculosis?', 'CD4 T cells and macrophages', ['CD8 T cells and NK cells', 'B cells and macrophages', 'CD4 T cells and neutrophils'], ['M. tuberculosis lives inside macrophages, so it is hidden from antibodies.', 'Th1 CD4 cells release interferon-γ, which activates macrophages to kill the bacteria they have already swallowed.', 'TNF-α keeps granulomas intact, which is why anti-TNF drugs can reactivate latent TB.']],
  ['PL-071', 'MECHANISM', 'ARDS', 'Urosepsis with shock, then bilateral infiltrates and refractory hypoxemia — lung pathology', 'Fluid accumulating in the alveoli', ['Wedge-shaped hemorrhagic necrosis', 'Noncaseating granulomas', 'Mucus plugs in the bronchioles'], ['Sepsis can cause acute respiratory distress syndrome by injuring the lung capillaries and alveolar lining.', 'Protein-rich fluid floods the alveoli and hyaline membranes form, so oxygen cannot reach the blood.', 'ARDS is managed with low tidal volume ventilation (about 6 mL/kg) and PEEP.']],
  ['PL-072', 'ASSOCIATION', 'Pneumonia', 'Weight loss, hypoxemia, bilateral ground-glass, cysts on silver stain — treatment', 'Trimethoprim–sulfamethoxazole', ['Caspofungin', 'Ganciclovir', 'Ceftriaxone and azithromycin'], ['A silver stain showing cysts identifies Pneumocystis jirovecii, which is typical when the CD4 count falls below 200.', 'Trimethoprim–sulfamethoxazole is the first-line treatment, and steroids are added when PaO₂ is below 70 mm Hg.', 'The same drug is used as prophylaxis once the CD4 count is below 200.']],
  ['PL-073', 'MECHANISM', 'TB & fungi', 'How does a tuberculous cavity form?', 'Aggregation of activated leukocytes', ['Bacterial toxin-induced necrosis', 'Intra-alveolar bacterial overgrowth', 'Obliterative airway inflammation'], ['M. tuberculosis has no classic tissue-destroying toxin: the damage is done by the immune response trying to contain it.', 'Activated macrophages and T cells form granulomas whose centres undergo caseous necrosis, which liquefies and drains into a bronchus.', 'Reactivation TB favours the lung apices, where the oxygen tension is highest.']],
  ['PL-074', 'ASSOCIATION', 'Neonatal lung', 'Preterm rupture of membranes at 30 weeks — which drug most improves the baby\'s survival?', 'Dexamethasone', ['Magnesium sulfate', 'Nifedipine', 'Terbutaline'], ['Corticosteroids given to the mother speed up maturation of the baby\'s type II pneumocytes, so they make surfactant sooner.', 'They are given between 24 and 34 weeks when delivery is expected within a week, and they lower respiratory distress, brain bleeds and death.', 'Maternal diabetes delays lung maturity, because fetal insulin inhibits surfactant production.']],
  ['PL-075', 'BUZZWORD', 'Lung transplant', 'Three months after lung transplant, lymphocytes cuff the small vessels on biopsy', 'Acute transplant rejection', ['Recurrence of primary disease', 'Pneumococcal pneumonia', 'Left ventricular dysfunction'], ['Lymphocytes packed around small vessels and airways in the first months after transplant are the hallmark of acute rejection.', 'It is mediated by recipient T cells reacting to donor MHC molecules, and it is treated with high-dose steroids.', 'Chronic rejection appears later as bronchiolitis obliterans.']],
  ['PL-076', 'MECHANISM', 'Asthma & COPD', 'Fatal asthma: eosinophils and thickened walls — which long-term drug prevents this?', 'Fluticasone', ['Albuterol', 'Montelukast', 'Theophylline'], ['Inhaled corticosteroids such as fluticasone are the main controller drugs for persistent asthma.', 'They switch off inflammatory gene transcription (by inhibiting NF-κB), which reduces eosinophilic inflammation and airway remodelling.', 'Their typical side effect is oral thrush, which is why patients rinse their mouth after each dose.']],
  ['PL-077', 'BUZZWORD', 'Pneumonia', 'Weeks of paroxysmal cough, inspiratory whoop and post-tussive vomiting after a cold', 'Gram-negative coccobacillus', ['Gram-positive diplococcus', 'Acid-fast bacillus', 'RNA virus'], ['This is pertussis, caused by Bordetella pertussis, a small gram-negative coccobacillus.', 'It runs through a catarrhal stage, then weeks of coughing fits with a whoop and vomiting, then slow recovery.', 'Pertussis toxin raises cAMP and causes a marked lymphocytosis; treat with a macrolide and give prophylaxis to close contacts.']],
  ['PL-078', 'ASSOCIATION', 'Lung cancer & pleura', 'Smoker with a central hilar mass and low sodium — biopsy?', 'Small cell lung cancer', ['Squamous cell carcinoma', 'Adenocarcinoma', 'Carcinoid tumor'], ['Low sodium with a central lung mass suggests SIADH, and small cell lung cancer is the tumour that most often makes ADH.', 'Small cell cancer is central, neuroendocrine, strongly linked to smoking and very aggressive.', 'It can also secrete ACTH or cause Lambert–Eaton syndrome, while squamous cell carcinoma instead causes hypercalcemia through PTHrP.']],
  ['PL-079', 'BUZZWORD', 'Pneumonia', 'What gives purulent sputum its green colour?', 'Myeloperoxidase', ['Epithelial necrosis', 'Hemolysis', 'High bacterial load'], ['Myeloperoxidase is a blue-green enzyme stored in neutrophil granules, so sputum full of neutrophils looks green.', 'It turns hydrogen peroxide and chloride into hypochlorous acid, which kills bacteria.', 'Myeloperoxidase deficiency is usually harmless but can predispose to Candida infections.']],
  ['PL-080', 'BUZZWORD', 'Lung structure', 'Inhaled particles stuck in the terminal bronchioles are cleared mainly by…', 'Ciliated cells', ['Alveolar macrophages', 'Goblet cells', 'Type I pneumocytes'], ['Cilia line the airways down to the terminal bronchioles and sweep mucus and trapped particles up and out.', 'This mucociliary escalator removes most inhaled particles.', 'Particles small enough to reach the alveoli are removed by macrophages instead.']],
  ['PL-081', 'TRIAD', 'Pneumonia', 'Toddler with barking cough, inspiratory stridor and steeple sign after a cold', 'Paramyxovirus', ['Rhinovirus', 'Parvovirus', 'Calicivirus'], ['This is croup, and its most common cause is parainfluenza virus, a member of the paramyxovirus family.', 'Swelling below the vocal cords produces the barking cough, stridor and the steeple sign on X-ray.', 'Treat with dexamethasone, adding nebulised epinephrine when there is stridor at rest.']],
  ['PL-082', 'MECHANISM', 'Gas exchange', 'Recovered from ARDS but breathless on exertion — which value stays raised?', 'Alveolar–arterial O₂ gradient', ['Diffusing capacity', 'Lung compliance', 'Forced vital capacity'], ['ARDS often heals with fibrosis, which thickens the barrier between alveolus and capillary.', 'Oxygen crosses more slowly, so arterial PO₂ falls further behind alveolar PO₂ and the A–a gradient rises.', 'Diffusing capacity, compliance and vital capacity all fall in fibrosis rather than rise.']],
  ['PL-083', 'MECHANISM', 'Cystic fibrosis', 'Nasal potential difference test in cystic fibrosis — what does the lining do?', 'Increased sodium absorption', ['Increased chloride secretion', 'Decreased bicarbonate secretion', 'Increased mucus water content'], ['CFTR normally restrains the epithelial sodium channel (ENaC), so without working CFTR the airway absorbs too much sodium.', 'Water follows the sodium out of the airway, which dehydrates the mucus and makes it thick.', 'The extra sodium absorption makes the surface more negative, which the nasal potential test measures when sweat testing is inconclusive.']],
  ['PL-084', 'MECHANISM', 'Gas exchange', 'Normal alveolar PO₂ but low end-capillary PO₂, while CO₂ equilibrates fully', 'Diffusion impairment', ['Intrapulmonary shunting', 'Poor alveolar ventilation', 'Normal V/Q matching'], ['When oxygen fails to equilibrate but CO₂ does, the barrier between alveolus and blood must be slowing diffusion.', 'CO₂ is about 20 times more soluble than oxygen, so it still crosses a thickened membrane.', 'Diffusion limitation is unmasked by exercise and altitude and is measured clinically as a low DLCO.']],
  ['PL-085', 'ASSOCIATION', 'TB & fungi', 'Advanced HIV with pneumonia from an encapsulated yeast — what does this organism usually cause?', 'Meningoencephalitis', ['Interstitial pneumonia', 'Esophagitis', 'Oral plaques'], ['Cryptococcus neoformans is inhaled into the lungs, but its most common serious disease is meningoencephalitis.', 'Cerebrospinal fluid shows a high opening pressure and a positive India ink stain or cryptococcal antigen.', 'Treat with amphotericin B and flucytosine, followed by fluconazole.']],
  ['PL-086', 'ASSOCIATION', 'Pneumonia', 'Consolidation with a sharp horizontal lower border on upright CXR — which lobe?', 'Right upper lobe', ['Right middle lobe', 'Left lower lobe', 'Right pleural space'], ['A sharp straight lower edge is made by the horizontal fissure, which exists only in the right lung.', 'The horizontal fissure separates the right upper lobe above from the right middle lobe below.', 'Right middle lobe pneumonia blurs the right heart border, and lower lobe pneumonia blurs the diaphragm (silhouette sign).']],
  ['PL-087', 'MECHANISM', 'Pharmacology', 'New asthma drug lowers IgE production — which cytokine does it block?', 'Interleukin-4', ['Interleukin-5', 'Interferon-γ', 'Interleukin-1'], ['Interleukin-4 tells B cells to switch to making IgE and pushes T cells toward the Th2 pathway.', 'Blocking it lowers IgE levels and reduces allergic asthma flares; dupilumab blocks the IL-4 receptor.', 'Interleukin-5 is the eosinophil cytokine, targeted by mepolizumab rather than an IgE-lowering drug.']],
  ['PL-088', 'BUZZWORD', 'Pneumonia', 'Lobar pneumonia with lancet-shaped diplococci — key virulence factor', 'Resistance to phagocytosis', ['Inhibition of protein synthesis', 'Blocking phagosome–lysosome fusion', 'Motility within host tissue'], ['Streptococcus pneumoniae has a thick polysaccharide capsule that stops neutrophils and macrophages from engulfing it.', 'The capsule antigens are what the pneumococcal vaccines are made from.', 'People without a spleen are especially vulnerable to encapsulated organisms like this one.']],
  ['PL-089', 'MECHANISM', 'Lung cancer & pleura', 'Pleural effusion next to a pneumonia, high in protein — main cause of the fluid', 'Increased pleural vascular permeability', ['Decreased plasma oncotic pressure', 'Increased thoracic hydrostatic pressure', 'Decreased thoracic lymphatic flow'], ['Protein escapes into the pleural space in large amounts only when inflammation makes the vessel walls leaky.', 'That makes the fluid an exudate: by Light\'s criteria the fluid-to-serum protein ratio is above 0.5 or the LDH ratio above 0.6.', 'Raised hydrostatic pressure or low oncotic pressure instead produce a low-protein transudate, as in heart failure or cirrhosis.']],
  ['PL-090', 'MECHANISM', 'Asthma & COPD', 'Chronic bronchitis with long-standing hypoxemia — expected additional finding', 'Increased erythropoietin production', ['Decreased functional residual capacity', 'Decreased RV afterload', 'Increased expiratory flow rates'], ['Chronic low oxygen is sensed by the kidney, which releases more erythropoietin.', 'Erythropoietin drives the marrow to make more red cells, producing secondary polycythemia.', 'In COPD the residual capacity rises, flow rates fall and right ventricular afterload increases, so the other options run the wrong way.']],
  ['PL-091', 'MECHANISM', 'Gas exchange', 'Venous red cells hold more chloride than arterial ones — which enzyme is responsible?', 'Carbonic anhydrase', ['Bisphosphoglycerate mutase', 'Na⁺/K⁺-ATPase', 'Pyruvate kinase'], ['In the tissues, carbonic anhydrase inside red cells turns CO₂ and water into carbonic acid, which splits into H⁺ and bicarbonate.', 'Bicarbonate leaves the cell in exchange for chloride through the band 3 transporter: the chloride shift.', 'About 70% of CO₂ travels in the blood as bicarbonate made this way.']],
  ['PL-092', 'MECHANISM', 'Pharmacology', 'Intubation relaxant: twitches fall evenly at first, then show train-of-four fade', 'Succinylcholine', ['Pancuronium', 'Tubocurarine', 'Dantrolene'], ['Succinylcholine is a depolarising blocker, which at first reduces all twitches equally without fade.', 'With prolonged exposure it moves into a phase II block that looks like a non-depolarising block, with fade.', 'Its risks include hyperkalemia, malignant hyperthermia and prolonged paralysis in pseudocholinesterase deficiency.']],
  ['PL-093', 'ASSOCIATION', 'TB & fungi', 'Spherules full of endospores in lung tissue — where has he been?', 'Arizona', ['Ohio caves', 'Pigeon lofts', 'Mississippi farms'], ['Spherules containing endospores are unique to Coccidioides immitis, which lives in the desert soil of the southwestern US.', 'It causes valley fever, often with erythema nodosum and joint pains.', 'Histoplasma is linked to bird and bat droppings in the Ohio and Mississippi valleys and to caves.']],
  ['PL-094', 'MECHANISM', 'Asthma & COPD', 'Young non-smoker with emphysema and PAS-positive globules in liver cells', 'Interalveolar septal destruction', ['Bronchial hyperreactivity', 'Interstitial infiltration', 'Intra-alveolar protein buildup'], ['α1-antitrypsin normally neutralises neutrophil elastase in the lung.', 'In α1-antitrypsin deficiency the misfolded protein is trapped in liver cells, so elastase destroys the alveolar walls unopposed.', 'The result is panacinar emphysema of the lower lobes at a young age, and sometimes cirrhosis.']],
  ['PL-095', 'ASSOCIATION', 'Neonatal lung', 'Term newborn in respiratory distress with a scaphoid abdomen and bowel in the chest', 'Underdeveloped lung tissue', ['Surfactant deficiency', 'Loss of negative pleural pressure', 'Raised wedge pressure'], ['A congenital diaphragmatic hernia lets abdominal organs into the chest, where they compress the developing lung.', 'The lung on that side is hypoplastic and pulmonary hypertension is common.', 'Most hernias are left-sided, through the posterolateral (Bochdalek) defect.']],
  ['PL-096', 'BUZZWORD', 'Lung cancer & pleura', 'Rind-like pleural tumour encasing the lung — what does the tissue show?', 'Cytokeratin-positive spindle cells', ['Caseating granulomas', 'Chromogranin-positive round cells', 'Whorled collagen fibres'], ['A tumour encasing the lung like a rind is malignant mesothelioma, which arises from the pleura.', 'It stains for cytokeratin and calretinin, and electron microscopy shows long, slender microvilli.', 'It is strongly linked to asbestos exposure decades earlier.']],
  ['PL-097', 'MECHANISM', 'Cystic fibrosis', 'Corrector plus potentiator therapy for a misfolded membrane channel — which disease?', 'Cystic fibrosis', ['Phenylketonuria', 'Sickle cell anemia', 'Alzheimer disease'], ['Correctors such as lumacaftor, tezacaftor and elexacaftor help misfolded CFTR fold and reach the cell surface.', 'Potentiators such as ivacaftor hold the channel open once it is there.', 'Ivacaftor on its own works for gating mutations such as G551D.']],
  ['PL-098', 'MECHANISM', 'Pharmacology', 'Besides calming inflammation, inhaled steroids directly do what for albuterol?', 'Increase β2-receptor responsiveness', ['Increase phosphodiesterase activity', 'Decrease mucus viscosity', 'Decrease surfactant production'], ['Corticosteroids increase the number of β2 receptors on airway smooth muscle and reverse the loss of response to β2 agonists.', 'That makes rescue albuterol work better.', 'The two drug classes help each other, which is why inhalers combine a steroid with a long-acting β2 agonist.']],
  ['PL-099', 'MECHANISM', 'Lung cancer & pleura', 'Malignant pleural effusion — why does fluid build up?', 'Occlusion of pleural lymphatic stomata', ['Raised pulmonary capillary pressure', 'Disruption of the thoracic duct', 'Decreased plasma oncotic pressure'], ['Pleural fluid normally drains through small openings (stomata) into the lymphatics of the parietal pleura.', 'Tumour cells spread over the pleura block those openings, so fluid enters faster than it can leave.', 'Malignant effusions are exudates and are often bloody; common sources are lung, breast and lymphoma.']],
  ['PL-100', 'BUZZWORD', 'Pneumonia', 'Teen from summer camp with walking pneumonia; his blood clumps when cooled', 'Mycoplasma pneumoniae', ['Legionella pneumophila', 'Coxiella burnetii', 'Klebsiella pneumoniae'], ['Clumping in the cold that reverses on warming is caused by cold agglutinins, IgM antibodies made in Mycoplasma infection.', 'Mycoplasma causes atypical pneumonia in young people in close quarters, with an X-ray that looks worse than the patient.', 'It has no cell wall, so it is invisible on Gram stain and is treated with a macrolide or doxycycline.']],
  ['PL-101', 'ASSOCIATION', 'Pneumonia', 'Infant with pneumonia living with a mother who smokes indoors — underlying factor', 'Impaired mucociliary function', ['Exaggerated airway reactivity', 'Inhibited B cell maturation', 'Reduced alveolar surface area'], ['Cigarette smoke paralyses and destroys cilia, so bacteria that would normally be swept out of the airway reach the lung.', 'Children exposed to second-hand smoke have more pneumonia, ear infections and asthma, and a higher risk of SIDS.', 'Removing the smoke exposure is the key preventive step.']],

  // ── PL-102 … PL-151 ──────────────────────────────────────────────────────
  ['PL-102', 'MECHANISM', 'Lung mechanics', 'Traumatic pneumothorax: hemithorax volume and lung compliance?', 'Volume up, compliance down', ['Volume down, compliance up', 'Volume down, compliance unchanged', 'Volume unchanged, compliance up'], ['Normally the lung pulls inward and the chest wall springs outward, and the pleural seal holds them together.', 'Once air enters the pleural space they separate: the chest wall springs out (volume rises) and the lung collapses.', 'A collapsed lung sits on the flat bottom of its pressure–volume curve, so it is stiff and hard to re-inflate (low compliance).']],
  ['PL-103', 'ASSOCIATION', 'Lung cancer & pleura', 'Milky, triglyceride-rich pleural fluid after a left neck dissection — what was injured?', 'Thoracic duct', ['Phrenic nerve', 'Esophagus', 'Lung parenchyma'], ['The thoracic duct runs up the left side and empties at the junction of the left subclavian and internal jugular veins.', 'Cutting it lets lymph leak into the chest, giving a chylothorax: milky fluid with triglycerides above 110 mg/dL.', 'Other causes of chylothorax are lymphoma, chest trauma and thoracic surgery.']],
  ['PL-104', 'TRIAD', 'Lung mechanics', 'Pneumothorax after CT-guided lung biopsy — percussion, fremitus, breath sounds', 'Hyperresonant, low fremitus, quiet sounds', ['Dull, low fremitus, quiet sounds', 'Dull, high fremitus, bronchial sounds', 'Hyperresonant, low fremitus, bronchial sounds'], ['Air in the pleural space is a poor conductor of vibration but resonates when tapped.', 'So a pneumothorax is hyperresonant, with reduced tactile fremitus and reduced breath sounds.', 'An effusion is dull with reduced fremitus, while consolidation is dull with increased fremitus and bronchial breathing.']],
  ['PL-105', 'MECHANISM', 'Pneumonia', 'Post-influenza pneumonia that destroys lung tissue — which virulence factor?', 'Leukocidin', ['M protein', 'Polysaccharide capsule', 'Lipooligosaccharide'], ['Panton–Valentine leukocidin is a Staphylococcus aureus toxin that punches holes in white cells.', 'Dying neutrophils release enzymes that cause necrotising, cavitating pneumonia and abscesses.', 'It is strongly linked to community-acquired MRSA, so vancomycin or linezolid is added when this picture appears.']],
  ['PL-106', 'BUZZWORD', 'Pneumonia', 'Unvaccinated child, drooling, tripod position, thumb sign — key virulence factor', 'Polyribosylribitol phosphate', ['M protein', 'Protein A', 'Trehalose dimycolate'], ['This is epiglottitis from Haemophilus influenzae type b, and its capsule is made of polyribosylribitol phosphate (PRP).', 'The capsule protects it from phagocytosis, and the Hib conjugate vaccine is built against it.', 'Epiglottitis is an airway emergency: secure the airway first, then treat with ceftriaxone.']],
  ['PL-107', 'BUZZWORD', 'Interstitial lung disease', 'Young Black woman, bilateral hilar nodes, noncaseating granulomas — main cell in BAL fluid', 'CD4⁺ lymphocytes', ['CD8⁺ lymphocytes', 'Eosinophils', 'Neutrophils'], ['Sarcoidosis is driven by Th1 CD4 T cells, so lung washings show many CD4 cells and a high CD4:CD8 ratio.', 'Those T cells organise macrophages into noncaseating granulomas.', 'Granulomas can make calcitriol, so sarcoidosis may cause high calcium as well as a raised ACE level.']],
  ['PL-108', 'MECHANISM', 'Asthma & COPD', 'What gives elastin its stretch and recoil?', 'Interchain lysine cross-links', ['Triple-helix chain assembly', 'Heavy hydroxylation', 'Interchain disulfide bridges'], ['Lysyl oxidase links lysine residues on neighbouring elastin chains into desmosine cross-links.', 'That network lets elastic fibres stretch and spring back, which gives the lung its elastic recoil.', 'The triple helix and heavy hydroxylation describe collagen, not elastin.']],
  ['PL-109', 'BUZZWORD', 'Lung cancer & pleura', 'HIV patient with a cherry-red airway lesion; spindle cells forming slit-like vessels', 'Human herpesvirus 8 infection', ['Carcinoid tumor', 'Cytomegalovirus infection', 'Squamous cell carcinoma'], ['Spindle cells forming slit-like vascular channels are Kaposi sarcoma, which is caused by human herpesvirus 8.', 'Kaposi sarcoma affects the skin, mouth, gut and lungs, usually when the CD4 count is low.', 'Treatment starts with antiretroviral therapy, with chemotherapy for extensive disease.']],
  ['PL-110', 'ASSOCIATION', 'Lung structure', 'Chest tube placed in the midaxillary line — which muscle is cut?', 'Serratus anterior', ['Latissimus dorsi', 'Pectoralis major', 'External oblique'], ['The serratus anterior covers the side of the chest at the level of the 4th to 6th ribs, so a tube there passes through it.', 'Tubes go in the "safe triangle" between pectoralis major, latissimus dorsi and the 5th intercostal space.', 'They are inserted just above a rib, because the intercostal vein, artery and nerve run under the rib above.']],
  ['PL-111', 'TRIAD', 'Pulmonary vascular', 'Recurrent nosebleeds, telangiectasias and dyspnea that is worse when sitting up', 'Vascular malformation', ['Pulmonary fibrosis', 'Valvular dysfunction', 'Airway obstruction'], ['This is hereditary hemorrhagic telangiectasia, an autosomal dominant disease of abnormal vessels.', 'Arteriovenous malformations in the lungs send blood straight from artery to vein, bypassing the alveoli: a right-to-left shunt.', 'Most AVMs lie at the lung bases, so sitting up sends more blood through them and worsens breathlessness.']],
  ['PL-112', 'BUZZWORD', 'Lung structure', 'Moving outward along the airway, which feature persists the furthest?', 'Cilia', ['Cartilage', 'Goblet cells', 'Mucous glands'], ['Cartilage and glands stop at the bronchi, and goblet cells stop at the terminal bronchioles.', 'Cilia continue further, down to the respiratory bronchioles.', 'That way any mucus made higher up can always be swept back toward the throat.']],
  ['PL-113', 'ASSOCIATION', 'Interstitial lung disease', 'Pressure–volume curve flattened and shifted right — stiff lungs', 'Pulmonary fibrosis', ['α1-antitrypsin deficiency', 'Bronchial asthma', 'Pulmonary arterial hypertension'], ['Compliance is the change in volume for a change in pressure, and a flat curve means the lungs barely inflate.', 'Fibrosis lays down stiff collagen, so it lowers compliance.', 'Emphysema from α1-antitrypsin deficiency does the opposite: the lungs become floppy and compliance rises.']],
  ['PL-114', 'ASSOCIATION', 'Pneumonia', 'Heavy drinker with poor teeth, foul sputum and a cavity — what must therapy cover?', 'Aerobic and anaerobic organisms', ['β-lactam–resistant staphylococci', 'Intestinal gram-negative flora', 'Cell wall–deficient bacteria'], ['This is a lung abscess from aspirated mouth contents, which happens when alcohol blunts the gag reflex.', 'Mouth flora is a mix of aerobes and anaerobes such as Peptostreptococcus, Prevotella and Fusobacterium.', 'Ampicillin–sulbactam or clindamycin covers both groups.']],
  ['PL-115', 'BUZZWORD', 'TB & fungi', 'Transplant patient with a lung lesion and brain abscess; branching filamentous rods', 'Partial acid-fastness', ['Anaerobic growth', 'Angioinvasion', 'Intracellular multiplication'], ['Branching filaments with lung and brain disease in an immunosuppressed patient is Nocardia, which is weakly acid-fast.', 'Actinomyces looks similar but is anaerobic, not acid-fast, and forms sulfur granules.', 'Remember SNAP: Sulfonamides for Nocardia, Actinomyces gets Penicillin.']],
  ['PL-116', 'ASSOCIATION', 'Lung cancer & pleura', 'Most common cancer after asbestos exposure arises from which tissue?', 'Bronchial epithelium', ['Pleural mesothelium', 'Bladder epithelium', 'Nasopharyngeal epithelium'], ['Bronchogenic carcinoma is the most common cancer in people exposed to asbestos.', 'Mesothelioma is more specific to asbestos but much rarer.', 'Smoking and asbestos multiply each other\'s lung cancer risk, so stopping smoking matters most.']],
  ['PL-117', 'MECHANISM', 'Pneumonia', 'Lobar consolidation on chest X-ray — what is filling the alveoli?', 'Leaked protein-rich fluid', ['Raised capillary hydrostatic pressure', 'Fibroblasts and matrix deposition', 'Mucous gland hyperplasia'], ['In lobar pneumonia, cytokines make capillaries leaky, so protein-rich fluid and neutrophils fill the alveoli.', 'The lobe goes through congestion, red hepatisation, grey hepatisation and resolution.', 'On examination it is dull to percussion with increased fremitus and bronchial breath sounds.']],
  ['PL-118', 'MECHANISM', 'Lung cancer & pleura', 'Pneumonia with an effusion: normal pH and glucose, high protein — what is happening?', 'Sterile exudate entering the pleura', ['Raised capillary hydrostatic pressure', 'Lymphatic obstruction', 'Low capillary oncotic pressure'], ['Inflammation next to the pleura makes its vessels leaky, so protein-rich fluid seeps in.', 'Normal pH and glucose show the bacteria have not entered the fluid, so this is an uncomplicated parapneumonic effusion.', 'A pH below 7.2, glucose below 60 or organisms on Gram stain mean a complicated effusion that needs drainage.']],
  ['PL-119', 'MECHANISM', 'Pulmonary vascular', 'Sudden hypoxemia three days after a femur fracture — main cause', 'Ventilation–perfusion mismatch', ['Alveolar hypoventilation', 'Primary diffusion impairment', 'Low O₂-carrying capacity'], ['A pulmonary embolism blocks flow to part of the lung, so that area is ventilated but unperfused.', 'Blood is diverted through the rest of the lung faster than it can be fully oxygenated, creating low V/Q areas.', 'The A–a gradient is raised, which separates this from hypoventilation.']],
  ['PL-120', 'ASSOCIATION', 'Asthma & COPD', 'COPD exacerbation with purulent sputum — classic bacterial trigger', 'Haemophilus influenzae', ['Klebsiella pneumoniae', 'Legionella pneumophila', 'Streptococcus pyogenes'], ['Nontypeable Haemophilus influenzae is one of the three bacteria most often found in COPD exacerbations.', 'The other two are Streptococcus pneumoniae and Moraxella catarrhalis.', 'Antibiotics are given when sputum becomes purulent, along with bronchodilators and steroids.']],
  ['PL-121', 'ASSOCIATION', 'Lung cancer & pleura', 'Smoker\'s bronchial lining turns squamous — which disease shows the same process?', 'Barrett esophagus', ['Cervical cancer', 'Minimal change disease', 'Hypertrophic cardiomyopathy'], ['Swapping one mature cell type for another that better tolerates irritation is called metaplasia.', 'Barrett esophagus is the same process: squamous lining becomes intestinal-type columnar lining because of acid reflux.', 'Metaplasia can be reversed, but it can also progress to dysplasia and cancer.']],
  ['PL-122', 'MECHANISM', 'Lung structure', 'Coal dust lodged in the respiratory bronchioles and alveoli is cleared by…', 'Phagocytosis', ['Mucociliary transport', 'Coughing and sneezing', 'Upper airway trapping'], ['Particles that reach beyond the cilia can only be removed by alveolar macrophages engulfing them.', 'Dust-filled macrophages release cytokines that drive fibrosis, which causes coal workers\' pneumoconiosis.', 'Larger particles (2–10 µm) are trapped higher up and cleared by the mucociliary escalator.']],
  ['PL-123', 'ASSOCIATION', 'Acid–base', 'Found unresponsive after an overdose: low pH, high PaCO₂, normal bicarbonate', 'Uncompensated respiratory acidosis', ['Respiratory acidosis, renal compensation', 'Metabolic acidosis, respiratory compensation', 'Respiratory alkalosis, renal compensation'], ['Sedative overdose slows breathing, so CO₂ builds up and the pH falls: respiratory acidosis.', 'The kidneys need days to raise bicarbonate, so in a fresh event it is still normal.', 'In acute respiratory acidosis bicarbonate rises only about 1 mEq/L for each 10 mm Hg rise in PaCO₂.']],
  ['PL-124', 'MECHANISM', 'TB & fungi', 'First week after inhaling Mycobacterium tuberculosis — what is happening?', 'Intracellular bacterial proliferation', ['Epithelioid change of macrophages', 'Interferon secretion by T cells', 'Caseous necrosis'], ['For the first few weeks the bacteria multiply freely inside alveolar macrophages that cannot yet kill them.', 'Only after about three weeks do Th1 cells arrive and release interferon-γ, forming granulomas.', 'That is also when the tuberculin skin test turns positive.']],
  ['PL-125', 'ASSOCIATION', 'Immunology', 'Celiac disease and repeated pneumonias, then anaphylaxis during a transfusion', 'Selective IgA deficiency', ['Severe combined immunodeficiency', 'C1 inhibitor deficiency', 'ABO incompatibility'], ['Selective IgA deficiency is the most common primary immunodeficiency and is linked to celiac disease and sinopulmonary infections.', 'Patients can make anti-IgA antibodies, which react with IgA in donor blood and cause anaphylaxis.', 'They should receive washed or IgA-deficient blood products.']],
  ['PL-126', 'MECHANISM', 'Shock & sepsis', 'Septic shock — which hormone is inappropriately low?', 'Vasopressin', ['Nitric oxide', 'Interleukin-1', 'C-reactive protein'], ['Vasopressin stores are used up early in septic shock, so levels are low for the degree of hypotension.', 'Low-dose vasopressin is therefore added to norepinephrine as a second vasopressor.', 'Nitric oxide, interleukin-1 and CRP are all raised in sepsis.']],
  ['PL-127', 'MECHANISM', 'Exercise & altitude', 'At peak moderate exercise, which value rises?', 'Venous blood CO₂ content', ['Arterial blood CO₂ content', 'Arterial blood pH', 'Venous blood O₂ content'], ['Working muscle produces much more CO₂, which travels back to the lungs in venous blood.', 'Breathing increases in step, so arterial PCO₂ and pH stay normal.', 'Muscles also extract more oxygen, so venous O₂ content falls rather than rises.']],
  ['PL-128', 'BUZZWORD', 'Lung cancer & pleura', 'Lung tumour forming irregular glands in an ex-smoker', 'Adenocarcinoma of the lung', ['Squamous cell lung cancer', 'Small cell lung cancer', 'Malignant mesothelioma'], ['Gland formation defines adenocarcinoma, the most common lung cancer overall.', 'It usually arises in the periphery of the lung and often carries targetable mutations such as EGFR, ALK or KRAS.', 'Squamous cell cancer instead shows keratin pearls and intercellular bridges.']],
  ['PL-129', 'ASSOCIATION', 'Sleep & breathing control', 'Obstructive sleep apnea is worst in which sleep state?', 'REM sleep, lying supine', ['Non-REM sleep, lying on side', 'Non-REM sleep, lying supine', 'REM sleep, lying on side'], ['During REM sleep almost all skeletal muscle tone is switched off, including the muscles that hold the pharynx open.', 'Lying on the back lets gravity pull the tongue and soft palate backward.', 'Both effects together make the airway most likely to collapse; side sleeping helps some patients.']],
  ['PL-130', 'MECHANISM', 'Pharmacology', 'Why choose ketamine to intubate a patient in severe bronchospasm?', 'Sympathomimetic activity', ['Direct GABA agonism', 'Lower lipid solubility', 'Neuromuscular blocking effect'], ['Ketamine increases the body\'s own catecholamine release, which relaxes bronchial smooth muscle.', 'It also keeps blood pressure up and preserves airway reflexes.', 'Its drawbacks include vivid hallucinations on waking and increased secretions.']],
  ['PL-131', 'ASSOCIATION', 'Pulmonary vascular', 'Young woman with exertional syncope; autopsy shows a thick right ventricle only', 'Pulmonary arterial hypertension', ['Bicuspid aortic stenosis', 'Dilated cardiomyopathy', 'Wolff–Parkinson–White syndrome'], ['Thickening of the right ventricle alone means it has been pumping against high pulmonary pressure for a long time.', 'In pulmonary arterial hypertension the small arteries show medial hypertrophy, intimal fibrosis and plexiform lesions.', 'Fainting on exertion happens because the right heart cannot raise its output.']],
  ['PL-132', 'ASSOCIATION', 'Lung structure', 'Thoracentesis at the 10th rib in the midaxillary line — what is at risk?', 'Right hepatic lobe', ['Intercostal artery', 'Right lower lung lobe', 'Hepatic veins'], ['The pleural space reaches about the 10th rib in the midaxillary line, and the diaphragm and liver sit just below it.', 'A needle placed that low on the right can pierce the liver, and on the left the spleen.', 'Thoracentesis is done above a rib and no lower than the 9th intercostal space in the midaxillary line.']],
  ['PL-133', 'MECHANISM', 'Pneumonia', 'Pneumonia that has cavitated into an abscess — what destroyed the tissue?', 'Lysosomal enzymes from neutrophils', ['Interferon-γ from CD4 T cells', 'Major basic protein from eosinophils', 'TGF-β from macrophages'], ['Neutrophils sent to kill the bacteria release proteases and oxygen radicals into the surrounding lung.', 'Those enzymes liquefy the tissue, leaving a cavity with an air-fluid level.', 'Organisms that commonly form abscesses include Staphylococcus aureus, Klebsiella and anaerobes.']],
  ['PL-134', 'MECHANISM', 'Cystic fibrosis', 'Massive hemoptysis in a teenager with cystic fibrosis — where is the bleeding from?', 'Hypertrophied bronchial arteries', ['Hypertrophied pulmonary arteries', 'Vasculitic alveolar hemorrhage', 'Aorto-bronchial fistula'], ['Bronchial arteries come off the aorta, so they carry blood at systemic pressure.', 'In bronchiectasis chronic inflammation makes them large, twisted and fragile.', 'Life-threatening hemoptysis is treated by bronchial artery embolisation.']],
  ['PL-135', 'ASSOCIATION', 'Neonatal lung', 'Amniotic lipid that surges in the late third trimester vs one that stays flat', 'Lecithin rises, sphingomyelin flat', ['Phosphatidylglycerol rises, lecithin flat', 'Sphingomyelin rises, albumin flat', 'Albumin rises, lecithin flat'], ['Lecithin (phosphatidylcholine) is the main surfactant lipid and rises sharply as the fetal lungs mature.', 'Sphingomyelin stays roughly constant, so the lecithin-to-sphingomyelin ratio climbs.', 'A ratio above 2 suggests the lungs are mature enough to avoid respiratory distress syndrome.']],
  ['PL-136', 'MECHANISM', 'Pharmacology', 'Irritant bronchoconstriction abolished by cutting the vagus — drug with the same effect', 'Ipratropium', ['Albuterol', 'Theophylline', 'Zileuton'], ['Vagal reflexes narrow the airway by releasing acetylcholine onto M3 receptors on smooth muscle.', 'Ipratropium blocks those muscarinic receptors, mimicking a cut vagus nerve.', 'Muscarinic antagonists such as ipratropium and tiotropium are first-line bronchodilators in COPD.']],
  ['PL-137', 'ASSOCIATION', 'Lung mechanics', 'Where is total airway resistance highest?', 'Medium-sized bronchi', ['Terminal bronchioles', 'Respiratory bronchioles', 'Alveolar ducts'], ['Each small airway is narrow, but there are so many in parallel that their total cross-section is huge.', 'Resistance therefore peaks at the medium-sized bronchi, where flow is turbulent and total area is still limited.', 'This is why early small-airway disease is "silent" on routine resistance tests.']],
  ['PL-138', 'ASSOCIATION', 'Pneumonia', 'After a cruise: high fever, confusion, diarrhoea and dry cough — likely lab finding', 'Low serum sodium', ['Cold agglutinins', 'Raised eosinophil count', 'Gram-positive diplococci'], ['This picture is Legionnaires disease, and hyponatremia is its most common laboratory abnormality.', 'Legionella lives in water systems and is diagnosed with a urinary antigen test.', 'It stains poorly with Gram stain and is treated with a fluoroquinolone or azithromycin.']],
  ['PL-139', 'BUZZWORD', 'Interstitial lung disease', 'Older man, progressive dyspnea, basal subpleural honeycombing, no exposure', 'Idiopathic pulmonary fibrosis', ['Chronic hypersensitivity pneumonitis', 'Asbestosis', 'Cryptogenic organizing pneumonia'], ['Patchy fibrosis under the pleura at the lung bases, with honeycombing and no known cause, is idiopathic pulmonary fibrosis.', 'Patients have Velcro-like crackles, clubbing and restrictive lung function with a low DLCO.', 'Antifibrotic drugs, pirfenidone and nintedanib, slow its progression.']],
  ['PL-140', 'ASSOCIATION', 'Cystic fibrosis', 'Newborn with meconium ileus — most likely eventual cause of death', 'Pneumonia', ['Liver cirrhosis', 'Malabsorption', 'Enterocolitis'], ['Meconium ileus in a newborn is almost diagnostic of cystic fibrosis.', 'In cystic fibrosis it is the lung disease, with recurrent infection and bronchiectasis, that causes most deaths.', 'Pseudomonas aeruginosa and Staphylococcus aureus are the typical lung pathogens.']],
  ['PL-141', 'ASSOCIATION', 'Lung mechanics', 'Normal ageing of the lungs — TLC, RV and FVC?', 'TLC same, RV up, FVC down', ['TLC down, RV down, FVC down', 'TLC up, RV up, FVC up', 'TLC down, RV up, FVC down'], ['With age the lungs lose elastic recoil while the chest wall stiffens, and the two effects cancel for TLC.', 'Small airways close earlier on expiration, so more air is trapped and residual volume rises.', 'With a fixed TLC and a larger RV, the vital capacity must fall.']],
  ['PL-142', 'ASSOCIATION', 'Acid–base', 'Hours after a pulmonary embolism — typical arterial blood gas', 'High pH, low PaO₂, low PaCO₂', ['Low pH, low PaO₂, high PaCO₂', 'Normal pH, PaO₂ and PaCO₂', 'Low pH, normal PaO₂, low PaCO₂'], ['Hypoxemia and stimulated lung receptors make the patient breathe fast, lowering PaCO₂ and raising pH.', 'Oxygen stays low because of ventilation–perfusion mismatch.', 'The event is only hours old, so the kidneys have not yet lowered bicarbonate.']],
  ['PL-143', 'ASSOCIATION', 'Asthma & COPD', 'Autopsy shows chronic bronchitis — which kind of risk factor matters most?', 'Behavioral', ['Genetic', 'Occupational', 'Infectious'], ['Chronic bronchitis is caused mainly by cigarette smoking, which is a behavioural exposure.', 'Its hallmark is mucous gland enlargement, measured by a Reid index above 0.4.', 'Stopping smoking is the single most effective step against COPD.']],
  ['PL-144', 'ASSOCIATION', 'Asthma & COPD', 'A smoker quits at 48 — what happens to his FEV₁ curve?', 'Decline slows; no function regained', ['Function returns to never-smoker level', 'Decline continues at the same rate', 'Brief rise, then the same decline'], ['After quitting, the rate at which FEV₁ falls slows back toward the normal age-related decline.', 'Function already lost does not come back, because destroyed airways and alveoli do not regrow.', 'Quitting helps at any age, which is the key message of the Fletcher–Peto curve.']],
  ['PL-145', 'MECHANISM', 'Pharmacology', 'Asthma add-on that stops mast cells degranulating, whatever the trigger', 'Preventing mast cell degranulation', ['Blocking leukotriene receptors', 'Blocking IgE binding to mast cells', 'Inhibiting 5-lipoxygenase'], ['Cromolyn is a mast cell stabiliser that stops mast cells releasing preformed mediators such as histamine.', 'Because it works before the reaction starts, it is only useful as prevention, not during an attack.', 'It is very safe, which made it useful for children with mild asthma.']],
  ['PL-146', 'TRIAD', 'Asthma & COPD', 'Asthmatic with eosinophilia, high IgE, fleeting infiltrates and central bronchiectasis', 'Aspergillus fumigatus', ['Pseudomonas aeruginosa', 'Strongyloides stercoralis', 'Legionella pneumophila'], ['This is allergic bronchopulmonary aspergillosis, an allergic reaction to Aspergillus growing in the airways.', 'It occurs in people with asthma or cystic fibrosis and causes recurring infiltrates and central bronchiectasis.', 'Treatment is oral corticosteroids, often with itraconazole.']],
  ['PL-147', 'BUZZWORD', 'Lung transplant', 'Lung transplant recipient with pneumonitis; large cells with owl\'s-eye inclusions', 'Enveloped double-stranded DNA virus', ['Enveloped single-stranded RNA virus', 'Non-enveloped double-stranded DNA virus', 'Fungus with trophic and cystic forms'], ['Enlarged cells with owl\'s-eye inclusions identify cytomegalovirus, a herpesvirus.', 'All herpesviruses are enveloped viruses with a double-stranded DNA genome.', 'CMV is most common one to six months after transplant and is treated with ganciclovir.']],
  ['PL-148', 'BUZZWORD', 'TB & fungi', 'M. tuberculosis growing in serpentine cords — what does this reflect?', 'Virulence', ['Acid-fastness', 'Antibiotic resistance', 'Replication rate'], ['Cording is caused by cord factor (trehalose dimycolate), the main virulence factor of M. tuberculosis.', 'Cord factor damages mitochondria, blocks neutrophil migration and triggers TNF release that drives granulomas.', 'Acid-fastness comes from mycolic acids in the cell wall, which is a different property.']],
  ['PL-149', 'ASSOCIATION', 'Pneumonia', 'Lung abscess grows mixed mouth bacteria — most likely predisposing factor', 'Seizure disorder', ['Tobacco smoking', 'Mitral valve prolapse', 'Urinary infection'], ['Mouth bacteria in a lung abscess mean they were aspirated, usually while the person was unconscious.', 'Seizures, alcohol, sedatives and swallowing problems all impair the cough and gag reflexes.', 'Endocarditis causes a different picture: multiple round nodules from septic emboli.']],
  ['PL-150', 'MECHANISM', 'ARDS', 'Vomited while intoxicated, then rapid hypoxemia and bilateral infiltrates — main injury', 'Neutrophil oxidants and proteases', ['Autoantibody alveolar hemorrhage', 'Eosinophil invasion of lung tissue', 'Granulomas around inhaled antigen'], ['Inhaled stomach acid burns the alveolar lining, which is called aspiration pneumonitis.', 'Neutrophils pour in and release oxygen radicals and proteases, which widen the damage into ARDS.', 'Infection by mouth bacteria, aspiration pneumonia, can follow later.']],
  ['PL-151', 'MECHANISM', 'Lung mechanics', 'Ventilated patient: delivered minute ventilation exceeds alveolar ventilation — why?', 'Dead space volume', ['Functional residual capacity', 'Residual volume', 'Respiratory rate'], ['Part of each breath stays in the conducting airways and in alveoli without blood flow, so it never takes part in gas exchange.', 'Alveolar ventilation equals (tidal volume − dead space) × respiratory rate.', 'Physiologic dead space is the anatomic dead space plus the alveolar dead space.']],

  // ── PL-152 … PL-201 ──────────────────────────────────────────────────────
  ['PL-152', 'ASSOCIATION', 'Pulmonary vascular', 'Lung histology six hours after a large anterolateral MI', 'Engorged capillaries, pink alveolar fluid', ['Neutrophil-rich fluid in the airways', 'Hemosiderin-laden macrophages', 'Fat globules in the arterioles'], ['A failing left ventricle backs pressure into the lungs within hours, so the capillaries swell with blood.', 'Fluid pushed out by pressure contains few cells, so the alveoli fill with pale pink, cell-free fluid.', 'Hemosiderin-laden "heart failure cells" appear only with long-standing congestion, not after a few hours.']],
  ['PL-153', 'BUZZWORD', 'Neonatal lung', 'Infant born at 25 weeks: few, large, simplified alveoli and abnormal capillaries', 'Bronchopulmonary dysplasia', ['Pulmonary alveolar proteinosis', 'Cystic adenomatoid malformation', 'Cystic fibrosis'], ['Birth at 25 weeks interrupts lung development just as the alveoli are forming and dividing.', 'Oxygen and ventilator injury add to the damage, leaving fewer and larger alveoli: bronchopulmonary dysplasia.', 'It is defined by a continuing oxygen need at 36 weeks corrected age.']],
  ['PL-154', 'BUZZWORD', 'TB & fungi', 'Carpenter with chronic pneumonia; biopsy shows a big yeast with a broad-based bud', 'Blastomyces dermatitidis', ['Histoplasma capsulatum', 'Coccidioides immitis', 'Cryptococcus neoformans'], ['A large yeast with a single bud attached across a wide base is the signature of Blastomyces.', 'It lives in soil and rotting wood near waterways, which suits outdoor and woodworking exposure.', 'Its chronic pneumonia can look like tuberculosis or lung cancer on imaging.']],
  ['PL-155', 'BUZZWORD', 'Lung cancer & pleura', 'Pleural plaques with lower-lobe fibrosis — what do the scars contain?', 'Ferruginous bodies', ['Birefringent silicate particles', 'Carbon-laden macrophages', 'Coalescing granulomas'], ['Pleural plaques plus lower-lobe fibrosis is asbestosis.', 'Inhaled asbestos fibres get coated in iron and protein, forming golden-brown beaded rods called ferruginous bodies.', 'Silica and coal disease favour the upper lobes, whereas asbestosis favours the lower lobes.']],
  ['PL-156', 'MECHANISM', 'Acid–base', 'Panic attack in a stuck lift: dizziness, tingling and blurred vision — cause', 'Low arterial PaCO₂', ['Low arterial PaO₂', 'Low arterial pH', 'Raised A–a gradient'], ['Anxiety makes her hyperventilate, which blows off CO₂.', 'Low CO₂ constricts the brain\'s blood vessels, so she feels dizzy and her vision blurs.', 'The resulting alkalosis lowers ionised calcium, which causes tingling around the mouth and hand spasms.']],
  ['PL-157', 'BUZZWORD', 'ARDS', 'Major trauma and many transfusions, then ARDS — which cell barrier broke down?', 'Type I pneumocytes', ['Type II pneumocytes', 'Club cells', 'Ciliated epithelial cells'], ['The air–blood barrier is made of type I pneumocytes, a shared basement membrane and capillary endothelium.', 'When that barrier is destroyed, protein-rich fluid floods the alveoli and hyaline membranes form.', 'Recovery depends on type II pneumocytes dividing to replace the lost type I cells.']],
  ['PL-158', 'MECHANISM', 'Pulmonary vascular', 'Why most pulmonary emboli do not cause lung infarction', 'Collateral circulation', ['Endothelial tPA release', 'Intrapulmonary shunting', 'Decreased surfactant'], ['The lung receives blood from both the pulmonary arteries and the bronchial arteries.', 'When an embolus blocks a pulmonary artery, the bronchial supply usually keeps the tissue alive.', 'Infarcts happen when that backup fails, for example in heart failure, and are wedge-shaped and pleural-based.']],
  ['PL-159', 'MECHANISM', 'Exercise & altitude', 'Hard exercise: minute ventilation, V/Q ratio and mixed venous O₂', 'Ventilation up, V/Q up, venous O₂ down', ['Ventilation up, V/Q down, venous O₂ down', 'Ventilation up, V/Q same, venous O₂ up', 'Ventilation same, V/Q same, venous O₂ up'], ['Ventilation can rise much more than cardiac output, so the overall V/Q ratio increases.', 'Working muscle extracts more oxygen, so blood returning to the heart carries less.', 'Arterial PO₂ and PCO₂ stay normal because ventilation keeps pace.']],
  ['PL-160', 'SIDE_EFFECT', 'Pharmacology', 'White oral plaques after starting a daily asthma inhaler — how to prevent them?', 'Oral rinsing after inhaler use', ['Prophylactic antibiotics', 'Recommended vaccines', 'Periodic glucose monitoring'], ['Inhaled steroid that lands in the mouth suppresses local immunity and allows Candida to grow (thrush).', 'Rinsing and spitting after each dose, and using a spacer, wash the drug away.', 'Hoarseness is the other common local side effect of inhaled steroids.']],
  ['PL-161', 'MECHANISM', 'Asthma & COPD', 'Asthma sputum full of eosinophils and Charcot–Leyden crystals — which cytokine?', 'Interleukin-5', ['Interleukin-12', 'Interferon-γ', 'TGF-β'], ['Interleukin-5, made by Th2 cells, recruits eosinophils into the airway and keeps them alive.', 'Charcot–Leyden crystals come from eosinophil proteins, and Curschmann spirals are casts of mucus.', 'Drugs that block IL-5, such as mepolizumab, help severe eosinophilic asthma.']],
  ['PL-162', 'ASSOCIATION', 'Lung cancer & pleura', 'Ex-smoker who spends hours in his basement — which exposure raises his lung cancer risk?', 'Radon gas', ['Benzene solvent', 'Mold spores', 'Bird antigens'], ['Radon is a radioactive gas released from uranium in soil, and it collects in basements.', 'It is the second leading cause of lung cancer after smoking, and the leading cause in non-smokers.', 'Home testing and basement ventilation lower the exposure.']],
  ['PL-163', 'ASSOCIATION', 'Lung cancer & pleura', 'Heavy smoker with a central tumour and euvolemic hyponatremia — which biopsy marker?', 'Neural cell adhesion molecule', ['EGFR mutation', 'KRAS mutation', 'Vimentin filaments'], ['Low sodium without dehydration suggests SIADH, the classic paraneoplastic effect of small cell lung cancer.', 'Small cell cancer is neuroendocrine, so it stains for CD56 (NCAM), chromogranin and synaptophysin.', 'EGFR and KRAS mutations are typical of adenocarcinoma instead.']],
  ['PL-164', 'BUZZWORD', 'TB & fungi', 'Fungus ball inside an old TB cavity, with no tissue invasion', 'Chronic colonization', ['Contagious infection', 'Allergic inflammation', 'Invasive malignancy'], ['Aspergillus can grow inside an old cavity as a ball (aspergilloma) without invading the surrounding lung.', 'Because it does not invade, this is colonisation rather than true infection.', 'Its main danger is bleeding, which may need surgery; invasive aspergillosis is a different disease of neutropenic patients.']],
  ['PL-165', 'BUZZWORD', 'Asthma & COPD', 'Pathological index of chronic bronchitis severity', 'Gland thickness ÷ epithelium-to-cartilage wall', ['Gland thickness ÷ total wall thickness', 'Epithelium ÷ total wall thickness', 'Epithelium ÷ epithelium-to-cartilage wall'], ['This is the Reid index: mucous gland layer thickness divided by the wall from basement membrane to cartilage.', 'A normal Reid index is below 0.4, and it rises as the glands enlarge in chronic bronchitis.', 'Clinically, chronic bronchitis is a productive cough for 3 months a year for 2 years in a row.']],
  ['PL-166', 'ASSOCIATION', 'Asthma & COPD', 'Young non-smoking hiker with emphysema of the lung bases', 'Panacinar emphysema', ['Centriacinar emphysema', 'Subpleural blebs', 'Compensatory hyperinflation'], ['α1-antitrypsin deficiency leaves the whole acinus unprotected, so the whole acinus is destroyed: panacinar emphysema.', 'It mainly affects the lower lobes, where blood flow and protease delivery are greatest.', 'Smoking causes centriacinar emphysema instead, centred on the respiratory bronchioles of the upper lobes.']],
  ['PL-167', 'TRIAD', 'Interstitial lung disease', 'Hilar lymphadenopathy, anterior uveitis and parotid swelling — lymph node biopsy', 'Granulomas without central necrosis', ['Caseating granulomas with acid-fast bacilli', 'Reed–Sternberg cells', 'Small basophilic cells'], ['Hilar nodes with eye and salivary gland involvement is sarcoidosis.', 'Its defining lesion is a noncaseating granuloma, which separates it from tuberculosis.', 'Uveitis, parotid swelling and facial palsy together form Heerfordt syndrome.']],
  ['PL-168', 'ASSOCIATION', 'Cystic fibrosis', 'Organism that colonises most adults with cystic fibrosis and turns mucoid', 'Pseudomonas aeruginosa', ['Staphylococcus aureus', 'Haemophilus influenzae', 'Klebsiella pneumoniae'], ['Staphylococcus aureus dominates in childhood, but Pseudomonas aeruginosa takes over in adults with cystic fibrosis.', 'Mucoid strains make alginate, forming biofilms that resist antibiotics.', 'Chronic Pseudomonas infection speeds the decline in lung function.']],
  ['PL-169', 'MECHANISM', 'ARDS', 'ARDS hypoxemia that oxygen alone does not fix but PEEP does — what PEEP reduces', 'Intrapulmonary shunt effect', ['Anatomic dead space', 'Lung compliance', 'Right-to-left intracardiac shunt'], ['Flooded alveoli are still perfused but receive no air, so blood passes them without picking up oxygen: a shunt.', 'Extra oxygen cannot reach those alveoli, so it barely helps.', 'PEEP props the collapsed alveoli open again, which reduces the shunt and improves oxygenation.']],
  ['PL-170', 'MECHANISM', 'Immunology', 'Insect sting → hives, wheeze and hypotension within minutes — trigger', 'Antigen cross-linking surface IgE', ['Immune-complex deposition', 'Complement-mediated cytotoxicity', 'CD8 T cell hypersensitivity'], ['A previous sting coated his mast cells with venom-specific IgE.', 'This time the venom bridged two IgE molecules, which made the mast cells release histamine and other mediators: type I hypersensitivity.', 'Intramuscular epinephrine is the first treatment for anaphylaxis.']],
  ['PL-171', 'TRIAD', 'Pneumonia', 'Person who injects drugs: high fever, new murmur, multiple peripheral cavitating nodules', 'Tricuspid valve endocarditis', ['Miliary tuberculosis', 'Venous thromboembolism', 'Mycotic aortic aneurysm'], ['Injection drug use seeds the right-sided valves, most often with Staphylococcus aureus.', 'Infected fragments break off and lodge in the lungs as septic emboli, which form round nodules that cavitate.', 'The murmur is holosystolic at the left lower sternal border and gets louder on inspiration.']],
  ['PL-172', 'MECHANISM', 'Gas exchange', 'Acute dyspnea with both low PaO₂ and low PaCO₂ — what is the patient doing?', 'Alveolar hyperventilation', ['Respiratory muscle fatigue', 'Poor respiratory drive', 'Expiratory air trapping'], ['Breathing hard clears CO₂ easily, so PaCO₂ falls.', 'Extra breathing cannot fix hypoxemia caused by ventilation–perfusion mismatch, so PaO₂ stays low.', 'If PaCO₂ starts rising in a struggling patient, it is a warning that they are tiring.']],
  ['PL-173', 'MECHANISM', 'TB & fungi', 'What drives formation of the giant cells in a TB granuloma?', 'Cytokines from CD4 lymphocytes', ['Activation of CD8 lymphocytes', 'Neutrophil infiltration of alveoli', 'Fibroblast collagen production'], ['Th1 CD4 cells release interferon-γ, which activates macrophages into epithelioid cells.', 'Epithelioid cells fuse to form multinucleated Langhans giant cells, with nuclei arranged in a horseshoe.', 'Macrophages drive the Th1 response by releasing interleukin-12.']],
  ['PL-174', 'MECHANISM', 'Pharmacology', 'β2 agonist with a long fat-soluble tail that anchors it near the receptor', 'Salmeterol', ['Albuterol', 'Terbutaline', 'Levalbuterol'], ['Salmeterol\'s lipophilic side chain anchors in the membrane and binds a second site, so it acts for about 12 hours.', 'Long-acting β2 agonists must always be combined with an inhaled steroid in asthma.', 'Side effects of β2 agonists include tremor, palpitations and low potassium.']],
  ['PL-175', 'MECHANISM', 'Cystic fibrosis', 'Child with recurrent pneumonia and a faulty CFTR channel — how is it gated?', 'ATP gated', ['Voltage gated', 'Mechanically gated', 'Temperature gated'], ['CFTR is an ABC transporter that opens when ATP binds its two nucleotide-binding domains.', 'Before that, protein kinase A must phosphorylate its regulatory domain, which is why cAMP controls it indirectly.', 'In sweat glands CFTR reabsorbs chloride, while in the airways it secretes chloride.']],
  ['PL-176', 'ASSOCIATION', 'Pneumonia', 'Care home outbreak: pneumonia with diarrhoea, poorly staining rods, positive urine antigen', 'Building water distribution system', ['Contaminated ready-to-eat food', 'Colonised staff noses', 'Residents\' skin flora'], ['A positive urine antigen with poorly staining rods identifies Legionella pneumophila.', 'Legionella grows in water systems such as cooling towers, hot water tanks and showers.', 'It spreads by inhaling contaminated water droplets, not from person to person.']],
  ['PL-177', 'ASSOCIATION', 'ARDS', 'ARDS after acute pancreatitis — which value stays normal?', 'Pulmonary capillary wedge pressure', ['Capillary permeability', 'Lung compliance', 'Ventilation–perfusion matching'], ['In ARDS the lungs flood because the capillaries become leaky, not because pressure behind them rises.', 'So the wedge pressure, which reflects left atrial pressure, stays normal.', 'Pancreatitis triggers ARDS by releasing enzymes and cytokines into the blood.']],
  ['PL-178', 'MECHANISM', 'Immunology', 'Adults resisting a familiar flu strain are protected mainly by…', 'Antibodies against hemagglutinin', ['Antibodies against neuraminidase', 'T cells against nucleocapsid', 'Antibodies against RNA polymerase'], ['Hemagglutinin is the protein influenza uses to attach to sialic acid on respiratory cells.', 'Antibodies against it stop the virus entering cells, so they prevent infection altogether.', 'Neuraminidase releases new virus particles and is the target of oseltamivir.']],
  ['PL-179', 'ASSOCIATION', 'Lung cancer & pleura', 'Incidental calcified pleural plaques on CT — likely occupation?', 'Insulation manufacturing', ['Sandblasting', 'Coal mining', 'Aerospace manufacturing'], ['Pleural plaques are the most common sign of past asbestos exposure.', 'Asbestos was used in insulation, shipbuilding, roofing and plumbing.', 'Sandblasting causes silicosis, and aerospace work can cause berylliosis instead.']],
  ['PL-180', 'ASSOCIATION', 'Lung mechanics', 'Intrapleural pressure at FRC, the end of a quiet breath out', 'Minus 5 cm H₂O', ['Zero cm H₂O', 'Plus 5 cm H₂O', 'Minus 10 cm H₂O'], ['At functional residual capacity the inward pull of the lung exactly balances the outward spring of the chest wall.', 'That balance holds the pleural pressure at about −5 cm H₂O.', 'It becomes more negative during inspiration and turns positive only in forced expiration.']],
  ['PL-181', 'ASSOCIATION', 'Interstitial lung disease', 'Weight loss, night sweats, bilateral hilar nodes — but granulomas without necrosis', 'Sarcoidosis', ['Mycobacterium tuberculosis', 'Hodgkin lymphoma', 'Mycobacterium avium complex'], ['Bilateral hilar nodes with noncaseating granulomas point to sarcoidosis.', 'Tuberculosis and fungal infections usually produce caseating (necrotic) granulomas, which is the key distinction.', 'Sarcoidosis is a diagnosis of exclusion, so stains and cultures for organisms must be negative.']],
  ['PL-182', 'MECHANISM', 'Asthma & COPD', 'Heavy smoker with emphysema — which cells drive the damage?', 'Neutrophils', ['Eosinophils', 'Mast cells', 'Club cells'], ['Smoke draws neutrophils and macrophages into the airspaces, where they release elastase and other proteases.', 'Oxidants in smoke also inactivate α1-antitrypsin, so the proteases destroy alveolar walls unopposed.', 'This protease–antiprotease imbalance is the core mechanism of emphysema.']],
  ['PL-183', 'ASSOCIATION', 'Asthma & COPD', 'New wheeze that clears on holiday and returns at work — what is involved?', 'Exposure to inhaled allergens', ['Inherited protease inhibitor deficiency', 'Mutation in the BMPR2 gene', 'Infection with dimorphic fungi'], ['Symptoms that improve away from work and return on going back point to occupational asthma.', 'Common triggers include isocyanates in paint, flour, latex and animal proteins.', 'Serial peak-flow readings at and away from work confirm the link.']],
  ['PL-184', 'SIDE_EFFECT', 'Pharmacology', 'Dextromethorphan in a patient who takes sertraline — main concern', 'Drug–drug interaction', ['Respiratory depression', 'Liver injury', 'Rebound symptoms on stopping'], ['Dextromethorphan increases serotonin activity, and so does sertraline.', 'Together they can cause serotonin syndrome: agitation, fever, clonus and diarrhoea.', 'Dextromethorphan should also be avoided with MAO inhibitors, linezolid and tramadol.']],
  ['PL-185', 'TRIAD', 'Pneumonia', 'Fever, dullness, bronchial breath sounds and increased fremitus over one lobe', 'Neutrophil-rich exudate in the lung', ['Fluid in the pleural space', 'Spontaneous pleural rupture', 'Embolic segmental occlusion'], ['Alveoli filled with pus conduct sound better than air, so fremitus and breath sounds increase.', 'Solid lung is dull to percussion, which completes the picture of consolidation from pneumonia.', 'A pleural effusion is also dull, but it reduces fremitus and breath sounds.']],
  ['PL-186', 'ASSOCIATION', 'Pneumonia', 'HIV with a near-normal CD4 count and acute lobar pneumonia — most likely organism', 'Streptococcus pneumoniae', ['Pneumocystis jirovecii', 'Mycobacterium tuberculosis', 'Aspergillus fumigatus'], ['Streptococcus pneumoniae is the most common cause of community-acquired pneumonia at every CD4 count.', 'HIV raises the risk of pneumococcal pneumonia and bacteremia many times over.', 'Opportunists such as Pneumocystis usually appear only once the CD4 count falls below 200.']],
  ['PL-187', 'MECHANISM', 'Shock & sepsis', 'Septic shock with a high anion gap — what is the cause of the gap?', 'Decreased oxidative phosphorylation', ['Increased lipolysis and ketogenesis', 'Impaired renal HCO₃⁻ reabsorption', 'Increased protein breakdown'], ['Poor perfusion starves cells of oxygen, so they cannot complete oxidative phosphorylation.', 'Pyruvate is turned into lactate instead, and lactic acid widens the anion gap.', 'A lactate above 4 mmol/L marks severe sepsis.']],
  ['PL-188', 'ASSOCIATION', 'Pneumonia', 'Care home resident with dementia and old stroke — why did he get aspiration pneumonia?', 'Swallowing muscle dysfunction', ['Extended immobility', 'Impaired cellular immunity', 'Weak intercostal muscles'], ['Stroke and dementia can leave a person unable to swallow safely, so saliva and food go into the trachea.', 'Aspirated material usually lands in the right lower lobe, because the right main bronchus is wider and more vertical.', 'Swallow assessment and upright feeding lower the risk.']],
  ['PL-189', 'BUZZWORD', 'Immunology', 'Allergy skin test wheal and flare — which mediator is released first?', 'Histamine', ['Leukotriene D4', 'Prostaglandin D2', 'Platelet-activating factor'], ['Histamine is already made and stored in mast cell granules, so it is released within minutes.', 'Leukotrienes, prostaglandins and platelet-activating factor have to be synthesised first, so they come later.', 'Antihistamines must be stopped before skin testing, or the wheal will not appear.']],
  ['PL-190', 'MECHANISM', 'Gas exchange', 'Pneumonia patient\'s oxygen improves before the consolidation clears — why?', 'Restored hypoxic vasoconstriction', ['Decreased alveolar consolidation', 'Decreased Hb affinity for O₂', 'Increased red cell production'], ['Low oxygen in an alveolus normally makes its arteriole constrict, steering blood toward well-ventilated lung.', 'Early in pneumonia, inflammation blunts that reflex; as it recovers, less blood flows through the consolidated area.', 'Less blood wasted on the non-ventilated lobe means a better PaO₂, even though the lobe is still full.']],
  ['PL-191', 'BUZZWORD', 'TB & fungi', 'Caver in Missouri with flu-like pneumonia — what fills the macrophages?', 'Small intracellular yeasts', ['Spherules with endospores', 'Budding yeast with a thick capsule', 'Septate hyphae at acute angles'], ['Caves mean bat droppings, and bat droppings mean Histoplasma capsulatum.', 'Histoplasma is a tiny yeast that survives and multiplies inside macrophages.', 'It is endemic in the Ohio and Mississippi river valleys and can disseminate in the immunocompromised.']],
  ['PL-192', 'ASSOCIATION', 'TB & fungi', 'After a Great Lakes trip: mould at room temperature, single-budding yeast at 37 °C', 'Blastomyces dermatitidis', ['Aspergillus fumigatus', 'Rhizopus species', 'Malassezia furfur'], ['A fungus that is a mould in the cold and a yeast at body heat is dimorphic.', 'Among the dimorphic fungi, the Great Lakes region and a single broad-based bud point to Blastomyces.', 'Aspergillus and Rhizopus are moulds at every temperature, so they are not dimorphic.']],
  ['PL-193', 'ASSOCIATION', 'TB & fungi', 'Young man with pleurisy and an effusion not helped by levofloxacin — fluid analysis', 'Protein above 4.0 g/dL', ['Malignant cells on cytology', 'High triglyceride level', 'Neutrophil-predominant cells'], ['A tuberculous pleural effusion is an exudate, so its protein is high, often above 4 g/dL.', 'Its cells are mainly lymphocytes, and adenosine deaminase is raised.', 'Fluoroquinolones partly treat TB, which can mask it and delay the diagnosis.']],
  ['PL-194', 'ASSOCIATION', 'Lung structure', 'Stab wound just above the medial clavicle, with hypotension and dyspnea', 'Lung pleura', ['Carotid body', 'Accessory nerve', 'Inferior thyroid artery'], ['The apex of the lung and its pleura rise 2–3 cm above the medial clavicle.', 'A wound in that area can enter the chest and cause a pneumothorax.', 'The same risk applies when placing a subclavian or internal jugular line.']],
  ['PL-195', 'TRIAD', 'Pulmonary vascular', 'After a long-bone fracture: hypoxemia, confusion and chest petechiae', 'Long bone fracture', ['Deep vein thrombosis', 'Aspiration of gastric contents', 'Left ventricular dysfunction'], ['Marrow fat enters the blood when a long bone such as the femur breaks, and lodges in lung and brain vessels.', 'Fat embolism appears 1–3 days after injury with breathlessness, confusion and a petechial rash.', 'Fixing the fracture early lowers the risk.']],
  ['PL-196', 'MECHANISM', 'Interstitial lung disease', 'IPF tissue: type I cells, type II cells, basement membrane, fibroblasts', 'I down, II up, membrane damaged, fibroblasts up', ['I down, II down, membrane intact, fibroblasts up', 'I up, II down, membrane damaged, fibroblasts up', 'I down, II up, membrane intact, fibroblasts down'], ['In IPF, repeated injury kills type I pneumocytes, and type II cells multiply in an attempt to repair the lining.', 'The basement membrane is damaged, so normal repair fails.', 'TGF-β drives fibroblasts to proliferate and lay down collagen instead, creating scar.']],
  ['PL-197', 'ASSOCIATION', 'Lung mechanics', 'Severe obesity — expected lung function pattern', 'Low TLC, low ERV, normal RV', ['High TLC, normal ERV, high RV', 'Normal TLC, high ERV, high RV', 'High TLC, low ERV, normal RV'], ['Fat around the chest and abdomen stops the lungs expanding fully, which gives a restrictive pattern.', 'Expiratory reserve volume falls the most, while residual volume stays normal.', 'The FEV₁/FVC ratio is normal, because the airways themselves are not obstructed.']],
  ['PL-198', 'BUZZWORD', 'TB & fungi', 'Thick-walled spherules packed with endospores in a lung biopsy', 'Coccidioides immitis', ['Histoplasma capsulatum', 'Blastomyces dermatitidis', 'Sporothrix schenckii'], ['Spherules full of endospores are the tissue form of Coccidioides and are found in no other fungus.', 'It is breathed in from desert soil in the southwestern US, especially after dust storms.', 'It can spread to the skin, bone and meninges, and fluconazole is used for meningitis.']],
  ['PL-199', 'ASSOCIATION', 'Pulmonary vascular', 'Traveller found dead with a large clot in the pulmonary artery — where did it form?', 'Deep femoral vein', ['Coronary artery plaque', 'Bronchial artery', 'Right atrial appendage'], ['Most large pulmonary emboli come from clots in the deep veins of the thigh.', 'Long travel causes venous stasis, one part of Virchow\'s triad with endothelial injury and hypercoagulability.', 'A saddle embolus at the pulmonary artery bifurcation can cause sudden death.']],
  ['PL-200', 'MECHANISM', 'Pharmacology', 'Child in an asthma attack improves within minutes of an inhaler — what changed?', 'Bronchiolar smooth muscle tone', ['Airway inflammatory response', 'Pulmonary vascular resistance', 'Alveolar surfactant production'], ['The quick-relief inhaler is a β2 agonist such as albuterol, which raises cAMP in airway smooth muscle.', 'Higher cAMP relaxes the muscle, opening the airways within minutes.', 'Steroids act on inflammation and take hours, so they cannot explain a response this fast.']],
  ['PL-201', 'DEFICIENCY', 'Cystic fibrosis', 'Infant with cystic fibrosis vomiting and sleepy on a hot day — which electrolyte problem?', 'Hyponatremia', ['Hypernatremia', 'Hyperkalemia', 'Hyperchloremia'], ['In cystic fibrosis the sweat glands cannot reclaim sodium chloride, so sweat is very salty.', 'On a hot day the baby loses a lot of salt through the skin, and blood sodium falls.', 'This salt loss can also cause a metabolic alkalosis.']],

  // ── PL-202 … PL-243 ──────────────────────────────────────────────────────
  ['PL-202', 'MECHANISM', 'Interstitial lung disease', 'Pulmonary fibrosis with higher-than-normal expiratory flow rates — why?', 'Radial traction on airway walls', ['Increased lung compliance', 'Outward chest wall recoil', 'Thicker bronchiolar walls'], ['Scar tissue around the airways pulls outward on their walls and holds them wide open.', 'Air therefore leaves faster than the small lung volume would suggest, and the FEV₁/FVC ratio is normal or high.', 'Lung compliance falls in fibrosis, so it cannot be the explanation.']],
  ['PL-203', 'ASSOCIATION', 'Acid–base', 'Sedative overdose: PaO₂, PaCO₂ and A–a gradient (mm Hg)', 'PaO₂ 55, PaCO₂ 60, gradient 10', ['PaO₂ 45, PaCO₂ 30, gradient 30', 'PaO₂ 55, PaCO₂ 60, gradient 25', 'PaO₂ 45, PaCO₂ 30, gradient 10'], ['Too little breathing lets CO₂ rise and oxygen fall together.', 'The lungs themselves are healthy, so the gap between alveolar and arterial oxygen stays normal (about 10).', 'A normal A–a gradient with low oxygen points to hypoventilation or high altitude.']],
  ['PL-204', 'MECHANISM', 'Pulmonary vascular', 'Pulmonary arterial hypertension — blocking which substance treats the disease itself?', 'Endothelin', ['Angiotensin II', 'Serotonin', 'Aldosterone'], ['Endothelin-1 both constricts the small pulmonary arteries and makes their walls grow thicker.', 'Endothelin receptor antagonists such as bosentan and ambrisentan block both effects.', 'Other PAH drugs work on nitric oxide (sildenafil) or prostacyclin (epoprostenol) pathways.']],
  ['PL-205', 'ASSOCIATION', 'Exercise & altitude', 'Elderly woman with a stooped spine gets angina in the mountains — contributing factor', 'Decreased chest wall mobility', ['Increased chemoreceptor responsiveness', 'Increased lung elastic recoil', 'Decreased dead space ventilation'], ['The body\'s first response to altitude is to breathe more deeply and quickly.', 'A stiff, curved chest wall cannot expand enough to do that, so her oxygen level stays low.', 'Low oxygen makes her heart work harder with less supply, which brings on angina.']],
  ['PL-206', 'ASSOCIATION', 'Asthma & COPD', 'Which single result would best rule asthma OUT?', 'Negative methacholine challenge', ['Normal chest radiograph', 'Normal total serum IgE', 'No blood eosinophilia'], ['The methacholine challenge is very sensitive, so a negative test makes asthma unlikely.', 'A positive result is less specific, because COPD and allergic rhinitis can also react.', 'A normal X-ray, IgE or eosinophil count is common in asthma, so none of them excludes it.']],
  ['PL-207', 'MECHANISM', 'Asthma & COPD', 'Long-term smoker with declining lung function — which cell contributes most?', 'Neutrophils', ['Eosinophils', 'Mast cells', 'B lymphocytes'], ['In COPD, smoke draws neutrophils, macrophages and CD8 T cells into the airways.', 'Their proteases destroy alveoli and drive mucus overproduction.', 'Eosinophils and mast cells are the main cells of asthma, not COPD.']],
  ['PL-208', 'ASSOCIATION', 'Pulmonary vascular', 'V/Q scan: a segment that is ventilated but not perfused — underlying disease', 'Deep venous thrombosis', ['Endobronchial neoplasm', 'Spontaneous pneumothorax', 'Viral pleuritis with effusion'], ['Air reaching a segment with no blood flow means its artery is blocked, the classic picture of pulmonary embolism.', 'Most emboli start as deep vein thromboses in the legs.', 'A V/Q scan is chosen when CT contrast is unsafe, for example in kidney disease.']],
  ['PL-209', 'ASSOCIATION', 'Exercise & altitude', 'First week at high altitude: plasma volume, pulmonary resistance, cardiac output', 'Volume down, resistance up, output up', ['Volume up, resistance down, output down', 'Volume down, resistance down, output up', 'Volume up, resistance up, output down'], ['Low oxygen makes pulmonary arterioles constrict, raising pulmonary vascular resistance.', 'Heart rate and cardiac output rise to deliver more oxygen, while the kidneys shed fluid and plasma volume falls.', 'Over weeks, erythropoietin raises red cell mass and 2,3-BPG increases.']],
  ['PL-210', 'ASSOCIATION', 'Interstitial lung disease', 'Exertional dyspnea, dry cough, hilar nodes; biopsy shows granulomas without necrosis', 'Sarcoidosis', ['Hodgkin lymphoma', 'Churg–Strauss syndrome', 'Pulmonary alveolar proteinosis'], ['Noncaseating granulomas with enlarged hilar nodes are the hallmark of sarcoidosis.', 'It is more common, and often more severe, in African American women.', 'Lung function usually shows a restrictive pattern with a low DLCO.']],
  ['PL-211', 'MECHANISM', 'Pulmonary vascular', 'Angiography: contrast runs from a pulmonary artery straight into a vein', 'Increased right-to-left shunting', ['Impaired alveolar diffusion', 'Decreased minute ventilation', 'Raised pulmonary resistance'], ['Contrast skipping the capillary bed shows a pulmonary arteriovenous malformation.', 'Blood passing through it never meets alveolar air, so it reaches the left heart still deoxygenated.', 'Because it is a true shunt, giving 100% oxygen barely raises the PaO₂.']],
  ['PL-212', 'ASSOCIATION', 'Pneumonia', 'Stroke patient vomits while lying flat on his back — which lung segment is affected?', 'Posterior right upper lobe', ['Basal right lower lobe', 'Anterior left upper lobe', 'Right middle lobe'], ['Aspirated material follows gravity, and lying on the back the lowest parts are the posterior upper lobes and superior lower lobes.', 'The right side is favoured because the right main bronchus is wider and more vertical.', 'When the patient is upright, aspiration goes to the basal segments of the right lower lobe instead.']],
  ['PL-213', 'BUZZWORD', 'Lung structure', 'Elastase found in normal lung washings — which cells make it?', 'Alveolar macrophages', ['Type II pneumocytes', 'Club cells', 'Goblet cells'], ['In the alveolus, elastase comes from macrophages and from neutrophils that have moved in.', 'α1-antitrypsin, made in the liver, normally neutralises it.', 'When elastase outweighs its inhibitor, the alveolar walls are destroyed and emphysema results.']],
  ['PL-214', 'ASSOCIATION', 'Lung mechanics', 'Ageing with kyphosis: lung compliance, total compliance, dead space', 'Lung up, total down, dead space up', ['Lung down, total down, dead space up', 'Lung up, total up, dead space up', 'Lung up, total same, dead space down'], ['With age the lungs lose elastic recoil, so lung compliance rises.', 'The chest wall stiffens even more, and it wins, so total respiratory compliance falls.', 'Ventilation–perfusion matching worsens with age, so physiologic dead space increases.']],
  ['PL-215', 'BUZZWORD', 'Interstitial lung disease', 'Exertional desaturation; biopsy shows lymphocytes, loose granulomas and septal fibrosis', 'Hypersensitivity pneumonitis', ['Idiopathic pulmonary fibrosis', 'Pulmonary tuberculosis', 'Chronic bronchitis'], ['Hypersensitivity pneumonitis is an immune reaction to inhaled organic antigens such as bird proteins or mouldy hay.', 'Its biopsy shows lymphocytes and small, poorly formed granulomas, and chronic cases add fibrosis.', 'The most important treatment is avoiding the exposure, with steroids if needed.']],
  ['PL-216', 'BUZZWORD', 'Lung mechanics', 'Tall, thin young man with sudden one-sided chest pain and dyspnea at rest', 'Apical subpleural blebs', ['Panacinar emphysema', 'Centriacinar emphysema', 'Compensatory hyperinflation'], ['Small air blisters at the top of the lung can burst and let air into the pleural space.', 'This is primary spontaneous pneumothorax, typical of tall, thin young men, especially smokers.', 'Small ones resolve on their own, while large ones need aspiration or a chest tube.']],
  ['PL-217', 'TRIAD', 'Pneumonia', 'Smoker with very high fever, confusion and diarrhoea; sputum full of neutrophils but no organisms', 'Legionella pneumophila', ['Klebsiella pneumoniae', 'Mycoplasma pneumoniae', 'Mycobacterium kansasii'], ['Legionella lives inside cells and stains poorly, so the Gram stain shows neutrophils but no bacteria.', 'High fever, confusion, diarrhoea and low sodium together are the classic picture.', 'Smokers and people with chronic lung disease are at greater risk.']],
  ['PL-218', 'BUZZWORD', 'TB & fungi', 'Autopsy: a scarred lower-lobe nodule plus a calcified hilar node on the same side', 'Primary TB infection', ['Secondary TB disease', 'Hematogenous TB dissemination', 'Poor immunity to mycobacteria'], ['A first TB infection leaves a Ghon focus in the lung and an involved hilar node; together they form the Ghon complex.', 'Once they heal and calcify, they are called a Ranke complex.', 'Bacteria can stay dormant in them and reactivate years later, usually at the apex.']],
  ['PL-219', 'MECHANISM', 'Lung cancer & pleura', 'Walled-off empyema that will not drain through a chest tube — what should the drug do?', 'Activate fibrin-bound plasminogen', ['Inhibit factor Xa production', 'Inhibit platelet activity', 'Irritate the mesothelial lining'], ['Fibrin strands divide the pus into separate pockets, so a single tube cannot drain them.', 'Tissue plasminogen activator turns plasminogen into plasmin, which dissolves the fibrin and joins the pockets.', 'If that fails, the pleura is cleaned out surgically (decortication).']],
  ['PL-220', 'MECHANISM', 'Pulmonary vascular', 'Pulmonary arterial hypertension: prostacyclin, thromboxane, nitric oxide', 'PGI₂ down, TXA₂ up, NO down', ['PGI₂ up, TXA₂ down, NO up', 'PGI₂ down, TXA₂ up, NO up', 'PGI₂ down, TXA₂ down, NO down'], ['A damaged endothelium makes less of the mediators that relax vessels and slow growth: prostacyclin and nitric oxide.', 'It makes more of those that constrict and promote growth, such as thromboxane and endothelin.', 'Each imbalance is a drug target: epoprostenol, sildenafil and bosentan.']],
  ['PL-221', 'SIDE_EFFECT', 'Asthma & COPD', 'COPD flare given high-flow oxygen, then rising PaCO₂ and drowsiness — main reason', 'Ventilation–perfusion mismatch', ['Raised minute ventilation', 'Raised renal HCO₃⁻ reabsorption', 'Raised pulmonary resistance'], ['Extra oxygen relaxes the vessels in poorly ventilated lung, so blood flows back into areas that cannot clear CO₂.', 'Oxygen also makes hemoglobin release more CO₂ (the Haldane effect).', 'That is why oxygen in CO₂-retaining COPD is aimed at a saturation of 88–92%.']],
  ['PL-222', 'ASSOCIATION', 'Lung cancer & pleura', 'Pleural fluid in congestive heart failure — protein, LDH, glucose, cells', 'Protein 2, LDH 30, glucose 90, cells 500', ['Protein 4, LDH 90, glucose 10, cells 10,000', 'Protein 2, LDH 90, glucose 10, cells 10,000', 'Protein 4, LDH 30, glucose 90, cells 500'], ['Heart failure pushes fluid out by pressure through an intact membrane, producing a transudate.', 'A transudate is low in protein and LDH, has normal glucose and contains few cells.', 'Heart failure is the most common cause of a transudative effusion.']],
  ['PL-223', 'ASSOCIATION', 'Sleep & breathing control', 'Low PaO₂, high PaCO₂, normal A–a gradient and foggy thinking', 'Chronic hypoventilation', ['Right-to-left shunt', 'Decreased diffusing capacity', 'Destruction of lung tissue'], ['A normal A–a gradient means the lungs transfer gas normally.', 'Low oxygen with high CO₂ must therefore come from too little air moving in and out.', 'Causes include obesity hypoventilation, neuromuscular disease and sedatives; high CO₂ causes headache and mental fog.']],
  ['PL-224', 'ASSOCIATION', 'Pulmonary vascular', 'Familial pulmonary arterial hypertension — most appropriate drug', 'Bosentan', ['Enalapril', 'Clopidogrel', 'Etanercept'], ['Bosentan blocks endothelin receptors, reducing both constriction and wall thickening of the pulmonary arteries.', 'It can damage the liver, so liver enzymes are checked monthly, and it is teratogenic.', 'ACE inhibitors, antiplatelets and TNF blockers do not treat PAH.']],
  ['PL-225', 'MECHANISM', 'Pulmonary vascular', 'Acute pulmonary embolism — which value increases?', 'Physiologic dead space', ['Lung diffusion capacity', 'Functional residual capacity', 'Pulmonary compliance'], ['Alveoli beyond the clot are still ventilated but have no blood flow, so the air reaching them is wasted.', 'That wasted ventilation is counted as alveolar dead space.', 'As a result, end-tidal CO₂ falls even though arterial CO₂ is normal or low.']],
  ['PL-226', 'MECHANISM', 'Lung mechanics', 'Weaning trial: same minute ventilation but more wasted ventilation — breathing pattern', 'Rate up, tidal volume down', ['Rate up, tidal volume up', 'Rate down, tidal volume up', 'Rate down, tidal volume down'], ['Every breath wastes a fixed volume in the conducting airways (about 150 mL).', 'Small, fast breaths waste a larger share of each breath, so dead space ventilation rises.', 'Rapid, shallow breathing during a weaning trial predicts failure to come off the ventilator.']],
  ['PL-227', 'MECHANISM', 'TB & fungi', 'Which signal is most important for forming a caseating granuloma?', 'Interferon-γ', ['Interleukin-4', 'GM-CSF', 'Interferon-α'], ['Interferon-γ from Th1 cells turns ordinary macrophages into the epithelioid cells that build a granuloma.', 'TNF-α keeps the granuloma intact once it has formed.', 'Interferon-γ release assays use this same response to detect latent tuberculosis.']],
  ['PL-228', 'MECHANISM', 'Cystic fibrosis', 'Young man with bronchiectasis reaching the pleura and mucus-plugged airways — root cause', 'Impaired clearance of secretions', ['Inherited protease inhibitor deficiency', 'Protein buildup in the alveoli', 'Raised pulmonary venous pressure'], ['Thick mucus that cannot be cleared plugs the airways and invites repeated infection.', 'Each infection inflames and weakens the bronchial walls until they widen permanently: bronchiectasis.', 'Causes include cystic fibrosis, primary ciliary dyskinesia and allergic aspergillosis.']],
  ['PL-229', 'ASSOCIATION', 'Sleep & breathing control', 'Sleep study: airflow stops while the chest and abdomen keep moving', 'Upper airway obstruction', ['Advanced heart failure', 'Neuromuscular weakness', 'Severe ketoacidosis'], ['Continued chest and abdominal effort with no airflow means the drive to breathe is intact but the airway is blocked.', 'That is obstructive sleep apnea.', 'In central apnea, effort and airflow stop together, as in Cheyne–Stokes breathing in heart failure.']],
  ['PL-230', 'BUZZWORD', 'Pneumonia', 'Lancet-shaped diplococci from a lobar pneumonia — additional lab feature', 'Lysis in the presence of bile', ['Resistance to optochin', 'Catalase production', 'Growth in hypertonic saline'], ['Streptococcus pneumoniae dissolves in bile, because bile salts switch on its own autolysin enzyme.', 'It is also optochin-sensitive, catalase-negative and alpha-hemolytic.', 'Viridans streptococci look similar but are optochin-resistant and not bile-soluble.']],
  ['PL-231', 'ASSOCIATION', 'Pharmacology', 'A new drug blocks cell wall synthesis — which bacterium is resistant?', 'Mycoplasma hominis', ['Helicobacter pylori', 'Borrelia burgdorferi', 'Pasteurella multocida'], ['A drug that blocks cell wall building cannot affect an organism with no cell wall at all.', 'Mycoplasma has only a cholesterol-containing membrane, so β-lactams and vancomycin do nothing to it.', 'Mycoplasma infections are treated with macrolides, tetracyclines or fluoroquinolones.']],
  ['PL-232', 'MECHANISM', 'Exercise & altitude', 'Skier at 2,900 m develops dyspnea and pink frothy sputum after a few days', 'Alveolar–capillary membrane disruption', ['Embolic pulmonary artery occlusion', 'Excessive fall in PaCO₂', 'Increased red cell mass'], ['At altitude the pulmonary vessels constrict unevenly, so the vessels that stay open take all the pressure.', 'Their capillaries are torn open by the pressure, and fluid and blood leak into the alveoli: high-altitude pulmonary edema.', 'Treatment is descent and oxygen, with nifedipine to lower pulmonary pressure.']],
  ['PL-233', 'MECHANISM', 'Pulmonary vascular', 'Inherited pulmonary arterial hypertension — direct cause of the disease', 'Vascular smooth muscle proliferation', ['Hypoxic vasoconstriction', 'Raised left atrial pressure', 'Thrombotic arterial occlusion'], ['Inherited PAH usually comes from a BMPR2 mutation, which normally holds back smooth muscle growth.', 'Without that brake, cells in the small pulmonary arteries multiply and narrow them.', 'It is autosomal dominant with incomplete penetrance, so not every carrier is affected.']],
  ['PL-234', 'MECHANISM', 'Pulmonary vascular', 'Long-standing hypertension with orthopnea and high pulmonary pressures — cause', 'Increased pulmonary venous pressure', ['Hypoxic vasoconstriction', 'Thrombotic arterial obstruction', 'Increased pulmonary arterial flow'], ['A stiff left ventricle needs high filling pressure, which backs up through the left atrium into the pulmonary veins.', 'That raised venous pressure in turn raises pressure on the arterial side.', 'Left heart disease is the most common cause of pulmonary hypertension.']],
  ['PL-235', 'TRIAD', 'Lung cancer & pleura', 'Weight loss with a large right pleural effusion — finding over the right lower chest', 'Decreased tactile fremitus', ['Bronchial breath sounds', 'Increased resonance', 'Focal monophasic wheeze'], ['Fluid between the lung and chest wall muffles vibrations, so tactile fremitus is reduced.', 'An effusion is also dull to percussion and has quiet breath sounds.', 'A large effusion can push the trachea away from the affected side.']],
  ['PL-236', 'ASSOCIATION', 'Interstitial lung disease', 'Flow–volume test: FEV₁ and FVC both low, ratio normal or high', 'Idiopathic pulmonary fibrosis', ['Adult-onset asthma', 'Chronic obstructive disease', 'Bronchiectasis'], ['When FEV₁ and FVC fall together, the ratio stays normal or rises, which is a restrictive pattern.', 'Stiff, scarred lungs in fibrosis hold less air but empty quickly.', 'Asthma and COPD lower FEV₁ more than FVC, so the ratio falls.']],
  ['PL-237', 'BUZZWORD', 'Pneumonia', 'Unvaccinated toddler with an ear infection, then septic arthritis — virulence factor', 'Capsule', ['Cytotoxic exotoxin', 'Hemolysins', 'Hyaluronidase'], ['An unvaccinated child with otitis followed by invasive infection suggests Haemophilus influenzae type b.', 'Its polysaccharide capsule stops phagocytes engulfing it, so it can spread through the blood to a joint.', 'The Hib conjugate vaccine targets this capsule.']],
  ['PL-238', 'ASSOCIATION', 'Lung cancer & pleura', 'Never-smoking woman with a peripheral lung mass — most likely cancer type', 'Adenocarcinoma', ['Small cell carcinoma', 'Squamous cell carcinoma', 'Bronchial carcinoid'], ['Adenocarcinoma is the most common lung cancer in women and in people who have never smoked.', 'It typically arises in the periphery of the lung.', 'Squamous cell and small cell cancers are central and strongly linked to smoking.']],
  ['PL-239', 'ASSOCIATION', 'Asthma & COPD', 'Most common infectious trigger of a COPD exacerbation', 'Rhinovirus infection', ['Staphylococcal infection', 'Pulmonary embolism', 'Air pollution'], ['Infections cause most COPD exacerbations, and rhinovirus, the common cold virus, is the single most common trigger.', 'Bacterial triggers include Haemophilus influenzae, Streptococcus pneumoniae and Moraxella catarrhalis.', 'Influenza and pneumococcal vaccines reduce exacerbations.']],
  ['PL-240', 'TRIAD', 'Interstitial lung disease', 'Joint pains, tender shin nodules and an enlarged liver — liver biopsy', 'Scattered granulomas', ['Nodular regeneration', 'Centrilobular necrosis', 'Periportal fibrosis'], ['Joint pains with erythema nodosum point to sarcoidosis, which puts noncaseating granulomas in many organs.', 'The liver is commonly involved, often without symptoms.', 'Erythema nodosum with hilar nodes and arthritis is Löfgren syndrome, which has a good prognosis.']],
  ['PL-241', 'BUZZWORD', 'Pneumonia', 'Heavy drinker with currant-jelly sputum; encapsulated lactose-fermenting rods', 'Klebsiella pneumoniae', ['Pseudomonas aeruginosa', 'Moraxella catarrhalis', 'Haemophilus influenzae'], ['Klebsiella has a thick capsule and forms pink, mucoid colonies on MacConkey agar because it ferments lactose.', 'It causes severe pneumonia in people with alcohol use disorder or diabetes, often in the upper lobes.', 'The sputum is thick and bloody, like currant jelly, and the lung can cavitate.']],
  ['PL-242', 'ASSOCIATION', 'Gas exchange', 'Upright lung from base to apex: ventilation, perfusion and V/Q', 'Both fall toward the apex; V/Q rises', ['Both rise toward the apex; V/Q falls', 'Both fall; V/Q stays constant', 'Ventilation falls; perfusion constant'], ['Gravity pulls both air and blood toward the base, but it affects blood much more.', 'So at the apex perfusion is very low compared with ventilation, and the V/Q ratio is highest there.', 'The high oxygen tension at the apex is why reactivation tuberculosis favours it.']],
  ['PL-243', 'MECHANISM', 'Cystic fibrosis', 'Cystic fibrosis patient with sudden dyspnea, hypotension and absent breath sounds on one side', 'Loss of negative pleural pressure', ['Alveolar inflammatory consolidation', 'Diffuse bronchoconstriction', 'Bronchial obstruction with collapse'], ['A burst air space lets air into the pleural space, so the suction that holds the lung open is lost.', 'This is a secondary spontaneous pneumothorax, a known complication of cystic fibrosis.', 'Hypotension with tracheal shift means tension pneumothorax, which needs immediate needle decompression.']],
];
